/*
QuidEdge API worker. Bind existing D1 database as DB.
Initial schema below is for a NEW database only.
CREATE TABLE recruitment_events (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  kind TEXT NOT NULL CHECK (kind IN ('job','candidate','stage','activity','summary','score')),
  subject_id TEXT REFERENCES recruitment_events(id),
  event_date TEXT NOT NULL,
  payload TEXT NOT NULL CHECK (json_valid(payload) AND json_type(payload) = 'object'),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK ((kind IN ('stage','activity','score')) = (subject_id IS NOT NULL))
);
--> statement-breakpoint
CREATE TRIGGER recruitment_events_no_update BEFORE UPDATE ON recruitment_events
BEGIN
  SELECT RAISE(ABORT, 'Recruitment records are append-only');
END;
--> statement-breakpoint
CREATE TRIGGER recruitment_events_no_delete BEFORE DELETE ON recruitment_events
BEGIN
  SELECT RAISE(ABORT, 'Recruitment records are append-only');
END;

CREATE INDEX recruitment_events_subject_seq ON recruitment_events(subject_id, seq);
--> statement-breakpoint
CREATE INDEX recruitment_events_kind_seq ON recruitment_events(kind, seq);

*/
const stages = ['Sourced','Contacted','Replied','R1 Scheduled','R1 Review','R2 Prep','R2 Scheduled','R2 Review','Reference Check','Offer / Agreement','On Hold','Hired','Rejected','Withdrawn'];
const closed = ['Hired','Rejected','Withdrawn'];
const milestones = ['First outreach','Reply received','Follow-up sent','R1 completed','R2 brief sent','R2 completed','Writing task completed','References completed','Offer sent','Agreement / NDA signed','Interview no-show','Interview cancelled','Offer declined','Blocker update','Commission terms reviewed'];
const checklistItems = [
  ['terms','Role and payment terms confirmed'],
  ['writing','Writing / practical task reviewed'],
  ['references','References checked'],
  ['offer','Offer accepted'],
  ['agreement','Agreement completed'],
  ['nda','NDA completed']
];
const dateSL = (date = new Date()) => new Intl.DateTimeFormat('en-CA', {
  timeZone:'Asia/Colombo',year:'numeric',month:'2-digit',day:'2-digit'
}).format(date);
const groupStages = [
  ['Sourced',['Sourced','Contacted','Replied'],'amber'],
  ['Screening',['R1 Scheduled','R1 Review'],'blue'],
  ['Technical',['R2 Prep','R2 Scheduled','R2 Review','Reference Check'],'coral'],
  ['Offer',['Offer / Agreement'],'purple'],
  ['Hired',['Hired'],'green']
];
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({
  '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
}[c]));
function validDate(value) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const parsed = new Date(value + 'T00:00:00Z');
  return Number.isFinite(+parsed) && parsed.toISOString().slice(0,10) === value;
}
function stageProblem(payload, candidate, eventDate) {
  if (payload.stage === 'R1 Scheduled' && candidate.commission_ack && candidate.commission_ack !== 'Accepted') return 'Confirm that the candidate accepts the commission-only terms before scheduling Round 1.';
  if (!stages.includes(payload.stage)) return 'Choose a valid stage.';
  if (!String(payload.note || '').trim()) return 'Add the reason for this update.';
  if (!closed.includes(payload.stage)) {
    if (![payload.action,payload.due,payload.owner].every(Boolean)) return 'Set the next action, owner and due date.';
  }
  const slot = payload.stage === 'R1 Scheduled' ? payload.r1 : payload.stage === 'R2 Scheduled' ? payload.r2 : '';
  if (['R1 Scheduled','R2 Scheduled'].includes(payload.stage)) {
    if (!slot) return 'Set the interview date and time in Sri Lanka time.';
    if (slot.slice(0,10) < eventDate) return 'The interview cannot be earlier than the event date.';
  }
  if (payload.stage === 'Hired') {
    const missing = checklistItems.filter(([key]) => !['Complete','Waived'].includes(candidate.checklist[key]));
    if (missing.length) return 'Complete or waive each hiring checklist item before marking Hired.';
    if (!validDate(payload.start_date)) return 'Confirm the start date before marking Hired.';
  }
  return '';
}
function project(events) {
  const jobs = new Map();
  const candidates = new Map();
  for (const event of [...events].sort((a,b) => a.seq - b.seq)) {
    const p = event.payload;
    if (event.kind === 'job') {
      if (p.job_id) {
        const job = jobs.get(p.job_id);
        if (job) Object.assign(job,p,{id:p.job_id,revision:event.seq});
      } else {
        jobs.set(event.id,{status:'Open',headcount:'1',...p,id:event.id,revision:event.seq});
      }
    }
    if (event.kind === 'candidate') {
      candidates.set(event.id, {
        ...p,id:event.id,date:event.event_date,revision:event.seq,
        history:[event],r1:'',r2:'',checklist:{},documents:{cv:'Missing',cover:'Missing'},start_date:''
      });
    }
    const candidate = candidates.get(event.subject_id);
    if (!candidate) continue;
    candidate.history.push(event);
    candidate.revision = event.seq;
    if (event.kind === 'stage') {
      for (const key of ['stage','action','due','owner','blocker','r1','r2','start_date']) {
        if (key in p) candidate[key] = p[key];
      }
    }
    if (event.kind === 'activity') {
      if (p.event === 'Document stored' && ['cv','cover'].includes(p.document_type)) candidate.documents[p.document_type] = 'Uploaded';
      if (p.event === 'Commission terms reviewed') { candidate.commission_ack=p.commission_ack; candidate.commission_plan=p.commission_plan; }
      if (p.event === 'Hiring checklist updated') {
        for (const [key] of checklistItems) {
          if (key in p) candidate.checklist[key] = p[key];
        }
      }
      const completed = {
        'Writing task completed':['writing'],
        'References completed':['references'],
        'Agreement / NDA signed':['agreement','nda']
      }[p.event] || [];
      for (const key of completed) candidate.checklist[key] = 'Complete';
    }
  }
  return {jobs:[...jobs.values()].reverse(),candidates:[...candidates.values()].reverse()};
}
function attention(candidate, today = dateSL()) {
  if (closed.includes(candidate.stage)) return 'Closed';
  if (candidate.due && candidate.due < today) return 'Overdue';
  if (candidate.blocker || candidate.owner === 'Leadership') return 'Needs decision';
  if (!candidate.action || !candidate.due || !candidate.owner) return 'Missing next step';
  return candidate.due === today ? 'Due today' : 'On track';
}
function csvCell(value) {
  let text = String(value ?? '');
  if (/^[\s]*[=+@-]/.test(text)) text = "'" + text;
  return '"' + text.replaceAll('"','""') + '"';
}

function newId() {
  if (typeof crypto.randomUUID === 'function') return crypto.randomUUID();
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  bytes[6] = (bytes[6] & 15) | 64;
  bytes[8] = (bytes[8] & 63) | 128;
  const hex = Array.from(bytes,value => value.toString(16).padStart(2,'0')).join('');
  return hex.slice(0,8) + '-' + hex.slice(8,12) + '-' + hex.slice(12,16) + '-' +
    hex.slice(16,20) + '-' + hex.slice(20);
}

const eventFields = {
  job: {
    required:['title','department','location'],
    optional:['employment','headcount','target_date','brief','status','job_id','note','profile']
  },
  candidate: {
    required:['alias','job_id','source','stage','action','due','owner'],
    optional:['availability','notice','blocker','commission_ack','commission_plan','market']
  },
  stage: {
    required:['stage','note'],
    optional:['action','due','owner','blocker','r1','r2','start_date']
  },
  activity: {
    required:['event','note'],
    optional:['terms','writing','references','offer','agreement','nda','commission_ack','commission_plan']
  },
  summary: {required:['progress','priorities'],optional:['blockers']},
  score: {
    required:['round','recommendation','note'],
    optional:['score1','score2','score3','score4','reviewer']
  }
};
const uuid = /^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i;
const privateText = /[\w.+%-]+@[\w.-]+\.[a-z]{2,}|https?:\/\/|www\./i;
const apiHeaders = {'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'};
const json = (value,status = 200) => Response.json(value,{status,headers:apiHeaders});
const error = (message,status = 400) => json({error:message},status);
const toEvent = row => ({...row,payload:JSON.parse(row.payload)});

function validate(record) {
  if (!record || typeof record !== 'object') return 'Invalid record.';
  const {id,kind,subject_id,event_date,payload,expected_seq} = record;
  if (typeof id !== 'string' || !uuid.test(id) || !Object.hasOwn(eventFields,kind) || !validDate(event_date)) {
    return 'Choose a valid record type and event date.';
  }
  if (expected_seq !== undefined && (!Number.isSafeInteger(expected_seq) || expected_seq < 0)) {
    return 'Refresh this record before updating it.';
  }
  const linked = ['stage','activity','score'].includes(kind);
  if (linked ? typeof subject_id !== 'string' || !uuid.test(subject_id) : subject_id !== null) {
    return 'Select an existing candidate.';
  }
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return 'Invalid fields.';
  const {required,optional} = eventFields[kind];
  if (required.some(key => typeof payload[key] !== 'string' || !payload[key].trim())) {
    return 'Complete all required fields.';
  }
  for (const [key,value] of Object.entries(payload)) {
    if ((!required.includes(key) && !optional.includes(key)) || typeof value !== 'string' || value.length > 600) {
      return 'Invalid field or text longer than 600 characters.';
    }
    if (privateText.test(value)) return 'Public records must omit email addresses and links.';
    if (['due','start_date','target_date'].includes(key) && value && !validDate(value)) return 'Choose a valid date.';
    if (['r1','r2'].includes(key) && value) {
      if (!/^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d$/.test(value) || !validDate(value.slice(0,10))) {
        return 'Choose a valid interview date and time.';
      }
    }
    if (key.startsWith('score') && !['','1','2','3','4','5'].includes(value)) return 'Scores must be 1 to 5.';
  }
  if (payload.owner && !['COO','Leadership','Candidate'].includes(payload.owner)) return 'Choose a valid action owner.';
  if (kind === 'job') {
    if (payload.job_id && (!uuid.test(payload.job_id) || !payload.note?.trim())) return 'Add a reason for the position update.';
    if (payload.status && !['Open','Paused','Closed'].includes(payload.status)) return 'Choose a valid position status.';
    if (payload.headcount && !/^[1-9]\d{0,2}$/.test(payload.headcount)) return 'Headcount must be 1 to 999.';
  }
  if (payload.commission_ack && !['Pending','Accepted','Declined'].includes(payload.commission_ack)) return 'Choose a valid commission acknowledgement.';
  if (payload.commission_plan && !['10 / 20 / 30 recurring','Other agreed terms'].includes(payload.commission_plan)) return 'Choose a valid commission plan.';
  if (payload.profile && payload.profile !== 'client-acquisition-v1') return 'Choose a valid role profile.';
  if (kind === 'candidate') {
    if (payload.stage !== 'Sourced' || !uuid.test(payload.job_id)) return 'Select a position and start at Sourced.';
    if (!/^[A-Za-z0-9][A-Za-z0-9_-]{1,39}$/.test(payload.alias)) return 'Use a unique candidate code, such as QE-001 (2 to 40 characters).';
  }
  if (kind === 'activity') {
    if (payload.event === 'Hiring checklist updated') {
      if (checklistItems.some(([key]) => !['Pending','Complete','Waived'].includes(payload[key]))) {
        return 'Set every hiring checklist item.';
      }
    } else if (payload.event === 'Commission terms reviewed' && !['Pending','Accepted','Declined'].includes(payload.commission_ack)) return 'Confirm the candidate’s commission acknowledgement.';
    else if (!milestones.includes(payload.event)) return 'Choose a valid milestone.';
  }
  if (kind === 'score') {
    if (!['R1','R2'].includes(payload.round) || !['Advance','Hold','Reject'].includes(payload.recommendation)) {
      return 'Choose a valid scorecard round and recommendation.';
    }
    if (![1,2,3,4].some(i => payload['score' + i])) return 'Score at least one tested criterion.';
  }
  return '';
}
async function readRecord(request) {
  if (!/^application\/json(?:;|$)/i.test(request.headers.get('Content-Type') || '')) return null;
  const reader = request.body?.getReader();
  if (!reader) return null;
  const chunks = [];
  let bytes = 0;
  for (;;) {
    const {done,value} = await reader.read();
    if (done) break;
    bytes += value.byteLength;
    if (bytes > 12000) {
      await reader.cancel();
      return null;
    }
    chunks.push(value);
  }
  try {
    return JSON.parse(await new Blob(chunks).text());
  } catch {
    return null;
  }
}
async function jobHistory(db,id) {
  const rows = await db.prepare(
    "SELECT * FROM recruitment_events WHERE id=? OR (kind='job' AND json_extract(payload,'$.job_id')=?) ORDER BY seq"
  ).bind(id,id).all();
  return project(rows.results.map(toEvent)).jobs[0];
}
function sameRecord(saved,record) {
  return saved.kind === record.kind && saved.subject_id === record.subject_id &&
    saved.event_date === record.event_date && JSON.stringify(saved.payload) === JSON.stringify(record.payload);
}
async function api(request,env,url) {
  if (!['GET','POST'].includes(request.method)) {
    return new Response(null,{status:405,headers:{...apiHeaders,Allow:'GET, POST, OPTIONS'}});
  }
  if (!env.DB) return error('Shared storage is unavailable. Please retry.',503);
  const db = env.DB.withSession('first-primary');
  if (request.method === 'GET') {
    const after = Number(url.searchParams.get('after') || 0);
    if (!Number.isSafeInteger(after) || after < 0) return error('Invalid event cursor.');
    const rows = await db.prepare(
      'SELECT * FROM recruitment_events WHERE seq > ? ORDER BY seq LIMIT 500'
    ).bind(after).all();
    return json(rows.results.map(toEvent));
  }
  const record = await readRecord(request);
  const problem = validate(record);
  if (problem) return error(problem);
  const {id,kind,subject_id,event_date,payload} = record;
  const previous = await db.prepare('SELECT * FROM recruitment_events WHERE id=?').bind(id).first();
  if (previous) {
    const saved = toEvent(previous);
    return sameRecord(saved,record) ? json(saved,200) : error('This save ID already belongs to another record.',409);
  }
  const conditions = [];
  const parameters = [id,kind,subject_id,event_date,JSON.stringify(payload)];
  if (subject_id) {
    const rows = await db.prepare(
      'SELECT * FROM recruitment_events WHERE id=? OR subject_id=? ORDER BY seq'
    ).bind(subject_id,subject_id).all();
    const candidate = project(rows.results.map(toEvent)).candidates[0];
    if (!candidate) return error('Select an existing candidate.');
    if (kind === 'stage') {
      const stageError = stageProblem(payload,candidate,event_date);
      if (stageError) return error(stageError);
    }
    const revision = record.expected_seq ?? candidate.revision;
    conditions.push('COALESCE((SELECT MAX(seq) FROM recruitment_events WHERE id=? OR subject_id=?),0)=?');
    parameters.push(subject_id,subject_id,revision);
  }
  if (kind === 'job' && payload.job_id) {
    const job = await jobHistory(db,payload.job_id);
    if (!job) return error('Select an existing position.');
    const revision = record.expected_seq ?? job.revision;
    conditions.push("COALESCE((SELECT MAX(seq) FROM recruitment_events WHERE id=? OR (kind='job' AND json_extract(payload,'$.job_id')=?)),0)=?");
    parameters.push(job.id,job.id,revision);
  }
  if (kind === 'candidate') {
    const job = await jobHistory(db,payload.job_id);
    if (!job || job.status !== 'Open') return error('Choose an open position.');
    if(job.profile==='client-acquisition-v1' && (!['Pending','Accepted','Declined'].includes(payload.commission_ack) || !payload.commission_plan)) return error('Record the commission structure and candidate acknowledgement.');
    conditions.push("NOT EXISTS (SELECT 1 FROM recruitment_events WHERE kind='candidate' AND lower(trim(json_extract(payload,'$.alias')))=lower(?))");
    parameters.push(payload.alias);
    conditions.push("COALESCE((SELECT json_extract(payload,'$.status') FROM recruitment_events WHERE kind='job' AND (id=? OR json_extract(payload,'$.job_id')=?) ORDER BY seq DESC LIMIT 1),'Open')='Open'");
    parameters.push(job.id,job.id);
  }
  const where = conditions.length ? ' WHERE ' + conditions.join(' AND ') : '';
  await db.prepare(
    'INSERT INTO recruitment_events (id,kind,subject_id,event_date,payload) SELECT ?,?,?,?,?' + where + ' ON CONFLICT(id) DO NOTHING'
  ).bind(...parameters).run();
  const row = await db.prepare('SELECT * FROM recruitment_events WHERE id=?').bind(id).first();
  if (!row) {
    return error(kind === 'candidate' ? 'Candidate code already exists, or the position has closed. Refresh and check.' :
      'Another update was saved first. Refresh the record and review your changes.',409);
  }
  const saved = toEvent(row);
  return sameRecord(saved,record) ? json(saved,201) : error('Save ID conflict. Refresh and retry.',409);
}
// Private document payloads are forwarded only to the owner's Google deployment.
// Do not log request bodies, candidate names, document bytes or credentials.
const validDriveEndpoint = value => /^https:\/\/script\.google\.com\/macros\/s\/[A-Za-z0-9_-]+\/exec$/.test(value || '');
const driveConfigured = env => validDriveEndpoint(env.DRIVE_WEB_APP_URL) && typeof env.DRIVE_WEB_APP_SECRET==='string' && env.DRIVE_WEB_APP_SECRET.length>=32;
async function boundedJson(request,limit) {
  if (!/^application\/json(?:;|$)/i.test(request.headers.get('Content-Type') || '')) return null;
  const reader=request.body?.getReader(); if (!reader) return null;
  const chunks=[]; let size=0;
  for (;;) {const {done,value}=await reader.read(); if(done)break; size+=value.byteLength;
    if(size>limit){await reader.cancel();return null;} chunks.push(value);}
  try{return JSON.parse(await new Blob(chunks).text());}catch{return null;}
}
async function documentApi(request,env) {
  if(request.method!=='POST')return error('Use POST to upload a document.',405);
  if(!driveConfigured(env))return error('Google Drive upload needs owner setup. Your candidate record is safe; no document has been uploaded.',503);
  if(!env.DB)return error('Shared storage is unavailable.',503);
  const input=await boundedJson(request,7.1*1024*1024);
  if(!input || !uuid.test(input.id||'') || !uuid.test(input.candidate_id||'') ||
    !['cv','cover'].includes(input.document_type) || !['pdf','doc','docx'].includes(input.extension) ||
    typeof input.name!=='string' || input.name.trim().length<2 || input.name.trim().length>120 ||
    /[\x00-\x1f\x7f\u202a-\u202e\u2066-\u2069]/.test(input.name) ||
    typeof input.data!=='string' || input.data.length>6990508 ||
    (input.data.length%4!==0 || !/^[A-Za-z0-9+/]*={0,2}$/.test(input.data))) {
    return error('Enter the candidate name and choose a valid PDF, DOC or DOCX up to 5 MB.');
  }
  const raw=atob(input.data);
  if(raw.length===0 || raw.length>5*1024*1024)return error('Each document must be 1 byte to 5 MB.');
  const matches=input.extension==='pdf'?raw.startsWith('%PDF-'):input.extension==='doc'?
    [0xd0,0xcf,0x11,0xe0,0xa1,0xb1,0x1a,0xe1].every((b,i)=>raw.charCodeAt(i)===b):raw.startsWith('PK\x03\x04');
  if(!matches)return error('The document contents do not match its file extension.');
  const db=env.DB.withSession('first-primary');
  const row=await db.prepare("SELECT * FROM recruitment_events WHERE id=? AND kind='candidate'").bind(input.candidate_id).first();
  if(!row)return error('Save the candidate before uploading documents.',404);
  const candidate=toEvent(row);
  const duplicate=await db.prepare('SELECT * FROM recruitment_events WHERE id=?').bind(input.id).first();
  if(duplicate) {
    const saved=toEvent(duplicate);
    return saved.kind==='activity' && saved.subject_id===input.candidate_id && saved.payload.event==='Document stored' && saved.payload.document_type===input.document_type?
      json({event:saved,uploaded:true}):error('This upload request ID is already in use.',409);
  }
  const position=await jobHistory(db,candidate.payload.job_id);
  if(!position || position.profile!=='client-acquisition-v1')return error('This upload is for the Client Acquisition & Client Relations position.');
  let upstream;
  try {
    upstream=await fetch(env.DRIVE_WEB_APP_URL,{method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({...input,alias:candidate.payload.alias,secret:env.DRIVE_WEB_APP_SECRET}),
      redirect:'follow',signal:AbortSignal.timeout(60000)});
    if(!upstream.ok)throw new Error('upstream');
    upstream=await upstream.json();
  } catch {return error('Drive did not confirm the upload. Retry the same file; existing files will be reused.',502);}
  if(!upstream.ok)return error(upstream.code==='PUBLIC_FOLDER'?
    'The Google Drive destination is publicly shared. The owner must restrict it before candidate documents can be uploaded.':
    upstream.code==='BUSY'?'Drive is processing another upload. Retry shortly.':
    'Google Drive could not complete the upload. Ask the owner to check the Drive connection.',502);
  const payload={event:'Document stored',document_type:input.document_type,note:(input.document_type==='cv'?'CV':'Cover letter')+' stored in the private recruitment Drive folder.'};
  await db.prepare('INSERT INTO recruitment_events (id,kind,subject_id,event_date,payload) VALUES (?,?,?,?,?) ON CONFLICT(id) DO NOTHING')
    .bind(input.id,'activity',input.candidate_id,dateSL(),JSON.stringify(payload)).run();
  const saved=await db.prepare('SELECT * FROM recruitment_events WHERE id=?').bind(input.id).first();
  if(!saved || saved.subject_id!==input.candidate_id)return error('File uploaded; status confirmation needs a retry.',409);
  return json({event:toEvent(saved),uploaded:true},201);
}

export default {
  async fetch(request,env) {
    const url = new URL(request.url);
    if (['/api/events','/api/documents','/api/integrations'].includes(url.pathname)) {
      const origin = request.headers.get('Origin');
      const allowed = origin === 'https://levigamage06.github.io' || origin === 'https://quidedge-hire.pages.dev' || origin === url.origin;
      if (origin && !allowed) return error('This origin is not allowed.',403);
      const corsHeaders = allowed ? {'Access-Control-Allow-Origin':origin,Vary:'Origin'} : {};
      if (request.method === 'OPTIONS') {
        return new Response(null,{status:204,headers:{
          ...apiHeaders,...corsHeaders,'Access-Control-Allow-Methods':'GET, POST, OPTIONS',
          'Access-Control-Allow-Headers':'Content-Type','Access-Control-Max-Age':'600'
        }});
      }
      let response;
      try {
        response = url.pathname === '/api/events' ? await api(request,env,url) : url.pathname === '/api/documents' ? await documentApi(request,env) : request.method === 'GET' ? json({drive_ready:driveConfigured(env)}) : error('Method not allowed.',405);
      } catch {
        response = error('Shared storage is temporarily unavailable. Please retry.',503);
      }
      const result = new Response(response.body,response);
      for (const [key,value] of Object.entries(corsHeaders)) result.headers.set(key,value);
      return result;
    }
    const path = url.pathname === '/' ? '/index.html' : url.pathname;
    if (!Object.hasOwn(ASSETS,path)) return new Response('Not found',{status:404});
    if (!['GET','HEAD'].includes(request.method)) return new Response(null,{status:405,headers:{Allow:'GET, HEAD'}});
    const asset = ASSETS[path];
    const cache = url.searchParams.has('v') ? 'public, max-age=31536000, immutable' : 'no-cache';
    return new Response(request.method === 'HEAD' ? null : asset.body,{
      headers:{'Content-Type':asset.type,'Cache-Control':cache,'X-Content-Type-Options':'nosniff','X-Robots-Tag':'noindex'}
    });
  }
};


const ASSETS={"/index.html":{"body":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"theme-color\" content=\"#efefe2\">\n<title>QuidEdge · Recruitment</title>\n<link rel=\"stylesheet\" href=\"./styles.css?v=a625ed1a0ceb\">\n</head>\n<body>\n<a class=\"skip\" href=\"#app\">Skip to recruitment workspace</a>\n<header class=\"top\">\n  <a href=\"#overview\" class=\"brand\"><span class=\"mark\" aria-hidden=\"true\">✺</span>quidedge<span class=\"brand-dot\">.</span></a>\n  <nav aria-label=\"Recruitment navigation\" id=\"nav\">\n    <a href=\"#overview\">Overview</a><a href=\"#coo\">COO workspace</a><a href=\"#role\">Hiring role</a><a href=\"#pipeline\">Pipeline</a><a href=\"#activity\">Daily activity</a><a href=\"#interviews\">Interviews</a><a href=\"#guide\">Interview guide</a>\n  </nav>\n  <button id=\"sync\" class=\"pill\" type=\"button\" title=\"Refresh data\"><span class=\"indicator\"></span><span id=\"mode\">Connecting</span></button>\n</header>\n<main>\n  <div id=\"app\" tabindex=\"-1\"></div>\n</main>\n<dialog id=\"dialog\" aria-labelledby=\"dialog-title\"></dialog>\n<div id=\"notice\" role=\"status\" aria-live=\"polite\"></div>\n<script type=\"module\" src=\"./app.js?v=a625ed1a0ceb\"></script>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/styles.css":{"body":":root{color-scheme:light;--ink:#191b17;--muted:#64675c;--paper:#fafaf3;--line:#dedfd3;--gold:#f8c87c;--amber:#d99c44;--blue:#6587e7;--coral:#e68d72;--purple:#ae6bd9;--green:#72b580;font-family:Inter,Aptos,system-ui,sans-serif;color:var(--ink);background:#eeeee1}\n*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 8% 0,#e8ede5,transparent 62%),radial-gradient(ellipse at 100% 27%,#f7efdc,transparent 65%);min-height:100vh}a{color:inherit}button,input,select,textarea{font:inherit}button,a,input,select,textarea{outline-offset:4px}button{cursor:pointer}button:disabled{cursor:wait;opacity:.55}.top{min-height:78px;display:flex;align-items:center;justify-content:space-between;gap:14px;padding:10px clamp(16px,3vw,46px);flex-wrap:wrap}.brand{text-decoration:none;font-size:clamp(24px,3vw,36px);font-weight:800;letter-spacing:-.075em;display:flex;align-items:center;gap:8px}.brand-dot{color:#bb651f;margin-left:-6px}.mark{color:#be651f;font-size:1.2em;line-height:1}.top nav{display:flex;gap:5px;flex-wrap:wrap}.top nav a,.pill,.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;border-radius:999px;padding:10px 16px;border:1px solid var(--line);text-decoration:none;background:var(--paper);color:var(--ink);font-size:.86rem;white-space:nowrap}.top nav a.active{background:var(--ink);color:white;border-color:var(--ink)}.indicator{width:8px;height:8px;border-radius:100%;background:#aa6b23}.live .indicator{background:#398449}.error .indicator{background:#a5332b}.btn.primary{background:var(--gold);border-color:transparent;font-weight:650}.btn:hover,.pill:hover{filter:brightness(.96)}main{max-width:1600px;margin:auto;padding:18px clamp(16px,3vw,46px) 52px}.intro,.section-top,.form-actions,.toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.intro{margin-bottom:20px}.intro h1{font-size:clamp(31px,4vw,52px);line-height:1.02;letter-spacing:-.06em;margin:0 0 10px}.eyebrow{text-transform:uppercase;font-weight:750;letter-spacing:.13em;font-size:.69rem;color:#696b5f;margin:0 0 10px}.sub,.muted,small{color:var(--muted)}.sub{margin:0}.banner{border:1px solid #e9d8b5;background:#fff5df;border-radius:13px;padding:10px 14px;margin:0 0 14px;color:#624619;font-size:.84rem}.metrics{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin:0 0 12px}.metric,.panel{background:rgba(250,250,243,.86);border:1px solid rgba(255,255,255,.56);border-radius:24px}.metric{padding:16px 14px;display:flex;justify-content:space-between;align-items:center;gap:8px;min-width:0;text-align:left}.metric strong{display:block;font-size:clamp(26px,3.4vw,48px);line-height:1;letter-spacing:-.06em;margin-top:8px}.metric-label{font-size:.85rem;font-weight:600}.dots{display:grid;grid-template-columns:repeat(7,6px);gap:4px}.dots i{width:6px;height:6px;border-radius:50%;background:#e9ebe4}.dots i.on{background:var(--tone)}.panel{padding:clamp(14px,2vw,25px);margin-bottom:12px}.section-top{margin-bottom:14px}.section-top h2{margin:0;font-size:clamp(19px,2.6vw,29px);letter-spacing:-.045em}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;text-align:left;min-width:650px}th,td{border-bottom:1px solid var(--line);padding:13px 10px 13px 0;vertical-align:middle}tr:last-child td{border-bottom:0}th{text-transform:uppercase;font-size:.69rem;letter-spacing:.07em;color:#555a50}td{font-size:.89rem}td small{display:block;margin-top:3px}.tag{display:inline-block;max-width:100%;background:#ecece1;border-radius:999px;padding:5px 9px;font-size:.73rem;white-space:nowrap}.tag.good{background:#dcefdc;color:#295a36}.tag.warn{background:#ffe4da;color:#8a352b}.tag.blue{background:#e0e8fb;color:#2f5098}.row-actions{display:flex;gap:6px;align-items:center}.row-actions .btn{padding:6px 10px;font-size:.75rem}.avatar{display:inline-grid;place-items:center;background:#f5e0b9;border-radius:50%;width:31px;height:31px;margin-right:7px;font-size:.72rem;font-weight:800;color:#715320}.empty{padding:22px 0;color:var(--muted);margin:0}.toolbar{justify-content:flex-start}.toolbar input,.toolbar select{width:auto}.split{display:grid;grid-template-columns:1fr 1fr;gap:12px}.statline{display:flex;gap:8px;flex-wrap:wrap}.timeline{list-style:none;padding:0;margin:0}.timeline li{padding:12px 0;border-bottom:1px solid var(--line);overflow-wrap:anywhere}.timeline li:last-child{border:0}.timeline p{margin:5px 0;white-space:pre-wrap}.timeline time{font-size:.75rem;color:var(--muted)}dialog{border:1px solid var(--line);border-radius:22px;width:min(680px,calc(100% - 24px));max-height:90vh;background:var(--paper);color:var(--ink);padding:22px;box-shadow:0 16px 80px #2426172b}dialog::backdrop{background:#22251e6c}dialog h2{margin:0;letter-spacing:-.04em}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field{display:grid;gap:5px;font-size:.83rem;font-weight:650}.field.wide{grid-column:1/-1}input,textarea,select{min-width:0;width:100%;border:1px solid #cdcec1;background:#fffef8;border-radius:11px;padding:9px;color:var(--ink)}textarea{resize:vertical;min-height:65px}.form-actions{margin-top:14px;justify-content:flex-end}.form-error{color:#96352c;font-size:.85rem}.guide-item{padding:9px 0;border-bottom:1px solid var(--line);font-size:.9rem}.guide-item p{margin:4px 0}.guide-item small{display:block}details summary{cursor:pointer;font-weight:700;padding:10px 0}#notice{position:fixed;bottom:14px;right:14px;z-index:2;background:var(--ink);color:white;padding:10px 14px;border-radius:14px;max-width:calc(100% - 28px);font-size:.85rem}#notice:empty{display:none}.danger-text{color:#903425}.snapshot{line-height:1.55;white-space:pre-wrap;overflow-wrap:anywhere}\n@media(max-width:1050px){.dots{display:none}}@media(max-width:700px){.top nav{order:3;width:100%;overflow:auto;flex-wrap:nowrap}.metrics{grid-template-columns:repeat(3,1fr)}.metric{padding:12px}.split{grid-template-columns:1fr}.panel{border-radius:18px}.form-grid{grid-template-columns:1fr}.top nav a{padding:8px 11px}}@media(max-width:360px){.metrics{grid-template-columns:repeat(2,1fr)}}\n\n/* Workflow controls use the existing QuidEdge palette. */\n:focus-visible{outline:3px solid #8f4b0c;outline-offset:3px}\n.skip{position:fixed;top:-100px;left:16px;z-index:10;background:#fff;padding:12px;border-radius:8px}\n.skip:focus{top:12px}\n.btn,.pill{min-height:42px}\n.top nav a{min-height:42px}\n.metric{display:block}\n.metric .metric-label{display:block}\n.metric-caption{display:block;font-size:.72rem;color:var(--muted);margin-top:10px}\n.filters{display:grid;grid-template-columns:2fr repeat(5,minmax(110px,1fr));gap:10px;margin-bottom:12px}\n.filters .field{font-size:.76rem}\n.result-count,.hint,.public-note{font-size:.8rem;color:var(--muted);line-height:1.5}\n.public-note{background:#f1f0e4;padding:10px 12px;border-radius:10px}\n.required{color:#8c3e15}\nfieldset{border:1px solid var(--line);border-radius:12px;padding:12px;margin:0;min-width:0}\nlegend{padding:0 6px;color:var(--muted);font-size:.8rem}\nfieldset:disabled{opacity:.5}\n[hidden]{display:none!important}\n.draft-banner{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap;padding:12px;background:#e6eddf;border-radius:14px;margin-bottom:14px;font-size:.85rem}\n.pagination{display:flex;justify-content:flex-end;gap:8px;margin-top:15px}\n.checklist{list-style:none;padding:0}\n.checklist li{display:flex;gap:10px;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);padding:9px 0;font-size:.85rem}\ndialog{overscroll-behavior:contain}\ndialog h2{max-width:calc(100% - 85px)}\n#app:focus{outline:none}\n@media(max-width:1100px){.filters{grid-template-columns:repeat(3,minmax(0,1fr))}}\n@media(max-width:700px){\n  .filters{grid-template-columns:repeat(2,minmax(0,1fr))}\n  .metrics{grid-template-columns:repeat(5,minmax(0,1fr));gap:5px}\n  .metric{border-radius:14px;padding:12px 7px}\n  .metric-label{font-size:.68rem}\n  .metric strong{font-size:27px}\n  .metric-caption{display:none}\n  .scroll{overflow:visible}\n  table,thead,tbody,tr,td{display:block;min-width:0;width:100%}\n  thead{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}\n  tbody tr{padding:10px 0;border-bottom:1px solid var(--line)}\n  tbody tr:last-child{border:0}\n  td{display:flex;justify-content:space-between;gap:14px;align-items:center;border:0;padding:7px 0;flex-wrap:wrap;overflow-wrap:anywhere}\n  td::before{content:attr(data-label);color:var(--muted);font-size:.74rem;flex:0 0 95px}\n  td small{flex-basis:100%;text-align:right}\n  .row-actions{flex-wrap:wrap}\n  .form-grid .wide{grid-column:1/-1}\n  .top{gap:8px}\n  .top .pill{font-size:.72rem;padding:7px 10px}\n  .intro h1{font-size:34px}\n}\n@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}\n\n.coo-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.coo-stats .panel span{display:block;color:var(--muted);font-size:.84rem}.coo-stats strong{display:block;font-size:38px;margin-top:8px}.commission-lead{font-size:28px;font-weight:750;margin:4px 0}.commission-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:20px 0}.commission-grid>div{border:1px solid var(--line);border-radius:16px;padding:18px;background:#fff9ed}.commission-grid strong{display:block;font-size:34px}.commission-grid span{display:block;color:var(--muted);margin-top:6px}.benefit-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.benefit-grid h3{font-size:1rem}.role-list li{padding:7px 0;line-height:1.55}.panel p{line-height:1.6}.public-note{line-height:1.5}input[type=file]{font-size:.8rem}#upload-progress{font-size:.85rem;line-height:1.5}@media(max-width:850px){.coo-stats{grid-template-columns:repeat(2,1fr)}.benefit-grid{grid-template-columns:1fr 1fr}}@media(max-width:500px){.commission-grid,.benefit-grid{grid-template-columns:1fr}.commission-grid>div{padding:12px}.commission-grid strong{font-size:27px}.coo-stats strong{font-size:30px}}\n","type":"text/css; charset=utf-8"},"/app.js":{"body":"import guide from './guide.js?v=a625ed1a0ceb';\nimport {\n  stages,closed,milestones,checklistItems,dateSL,groupStages,project,attention,\n  escape as e,csvCell,stageProblem,newId\n} from './model.js?v=a625ed1a0ceb';\nimport {hiringRole,defaultRoleRecord} from './role.js';\nimport {checkDocument,privateFolderSearch,uploadDocument,driveRoot} from './documents.js';\nimport {append,loadEvents,apiBase} from './store.js?v=a625ed1a0ceb';\n\nconst app = document.querySelector('#app');\nconst dialog = document.querySelector('#dialog');\nconst mode = document.querySelector('#mode');\nconst sync = document.querySelector('#sync');\nconst notice = document.querySelector('#notice');\nconst owners = ['COO','Leadership','Candidate'];\nconst sources = ['Headhunting','Referral','Inbound','Other'];\nconst employmentTypes = ['Contract','Full-time','Part-time','Commission-based'];\nconst pageSize = 25;\nlet events = [];\nlet state = {jobs:[],candidates:[]};\nlet jobNames = new Map();\nlet candidateIndex = new Map();\nlet ready = false;\nlet failure = '';\nlet refreshing = false;\nlet saving = false;\nlet timer;\nlet focusReturn;\nlet pendingRecord = null;\nlet reportDate = dateSL();\nlet stageFilter = '';\nlet jobFilter = '';\nlet attentionFilter = '';\nlet ownerFilter = '';\nlet search = '';\nlet sort = 'recent';\nlet currentPage = 1;\nlet guideTrack = 'Client Acquisition & Relations';\nlet searchTimer;\nlet noticeTimer;\n\nconst page = () => ['overview','coo','role','pipeline','activity','interviews','guide'].includes(location.hash.slice(1)) ?\n  location.hash.slice(1) : 'overview';\nconst btn = (label,action,id = '',primary = false) =>\n  '<button type=\"button\" class=\"btn ' + (primary ? 'primary' : '') +\n  '\" data-action=\"' + e(action) + '\" data-id=\"' + e(id) + '\">' + e(label) + '</button>';\nconst tag = (text,type = '') => '<span class=\"tag ' + type + '\">' + e(text) + '</span>';\nconst empty = text => '<p class=\"empty\">' + e(text) + '</p>';\nfunction options(values,selected = '') {\n  return values.map(item => {\n    const [value,label] = Array.isArray(item) ? item : [item,item];\n    return '<option value=\"' + e(value) + '\"' + (String(value) === String(selected) ? ' selected' : '') +\n      '>' + e(label) + '</option>';\n  }).join('');\n}\nfunction table(head,rows) {\n  return '<div class=\"scroll\"><table><thead><tr>' +\n    head.map(h => '<th scope=\"col\">' + e(h) + '</th>').join('') +\n    '</tr></thead><tbody>' + rows.map(row => '<tr>' + row.map((cell,i) =>\n      '<td data-label=\"' + e(head[i]) + '\">' + cell + '</td>').join('') + '</tr>').join('') +\n    '</tbody></table></div>';\n}\nconst panel = (title,html,action = '') => '<section class=\"panel\"><div class=\"section-top\"><h2>' +\n  e(title) + '</h2>' + action + '</div>' + html + '</section>';\nconst heading = (title,subtitle,action = '') => '<div class=\"intro\"><div><p class=\"eyebrow\">QuidEdge / Operations</p>' +\n  '<h1>' + e(title) + '</h1><p class=\"sub\">' + e(subtitle) + '</p></div>' + action + '</div>';\nconst eventLabel = event => ({\n  job:event.payload.job_id ? 'Position updated' : 'Position opened',\n  candidate:'Candidate sourced',stage:event.payload.stage,activity:event.payload.event,\n  summary:'Daily summary',score:event.payload.round + ' scorecard'\n})[event.kind];\nconst jobTitle = id => jobNames.get(id) || 'Position unavailable';\nconst candidateById = id => candidateIndex.get(id);\nfunction storageRead() {\n  try { return JSON.parse(sessionStorage.getItem('qe-recruitment-draft') || 'null') }\n  catch { return null }\n}\nfunction storageWrite(value) {\n  try {\n    if (value) sessionStorage.setItem('qe-recruitment-draft',JSON.stringify(value));\n    else sessionStorage.removeItem('qe-recruitment-draft');\n  } catch { /* The form remains usable when browser storage is disabled. */ }\n}\nfunction ingest(incoming) {\n  if (!incoming.length) return false;\n  const known = new Set(events.map(event => event.id));\n  const fresh = incoming.filter(event => !known.has(event.id));\n  if (!fresh.length) return false;\n  events = events.concat(fresh).sort((a,b) => a.seq - b.seq);\n  state = project(events);\n  jobNames = new Map(state.jobs.map(job => [job.id,job.title]));\n  candidateIndex = new Map(state.candidates.map(candidate => [candidate.id,candidate]));\n  return true;\n}\nfunction candidateTable(candidates) {\n  if (!candidates.length) return empty('No candidates in this view. Add a candidate or adjust the filters.');\n  return table(['Candidate','Position','Stage','Next action','Attention','Actions'],candidates.map(candidate => {\n    const flag = attention(candidate);\n    return [\n      '<strong>' + e(candidate.alias) + '</strong><small>' + e(candidate.source) + '</small><small>CV: '+e(candidate.documents?.cv||'Missing')+' · Cover letter: '+e(candidate.documents?.cover||'Missing')+'</small>',\n      e(jobTitle(candidate.job_id)),\n      tag(candidate.stage,candidate.stage === 'Hired' ? 'good' : 'blue'),\n      e(candidate.action || 'Set the next step') + '<small>' + e(candidate.due || 'No due date') +\n        ' · ' + e(candidate.owner || 'No owner') + '</small>',\n      tag(flag,['Overdue','Needs decision','Missing next step'].includes(flag) ? 'warn' : ''),\n      '<div class=\"row-actions\">' + btn('View record','view',candidate.id) +\n        btn('Update','stage',candidate.id,true) + '</div>'\n    ];\n  }));\n}\nfunction overview() {\n  const candidates = state.candidates;\n  const openJobs = state.jobs.filter(job => job.status === 'Open');\n  const metrics = groupStages.map(([label,values,tone]) => {\n    const count = candidates.filter(candidate => values.includes(candidate.stage)).length;\n    return '<button class=\"metric\" type=\"button\" data-action=\"group\" data-id=\"' + e(label) +\n      '\" style=\"--tone:var(--' + tone + ')\"><span class=\"metric-label\">' + e(label) +\n      '</span><strong>' + count + '</strong><span class=\"metric-caption\">View candidates</span></button>';\n  }).join('');\n  const active = candidates.filter(candidate => !closed.includes(candidate.stage));\n  const queue = active.filter(candidate => attention(candidate) !== 'On track').sort((a,b) =>\n    (a.due || '9999').localeCompare(b.due || '9999'));\n  const jobRows = state.jobs.map(job => [\n    '<strong>' + e(job.title) + '</strong><small>' + e(job.employment || 'Terms to confirm') + '</small>',\n    e(job.department) + '<small>' + e(job.location) + '</small>',\n    String(candidates.filter(candidate => candidate.job_id === job.id && candidate.stage === 'Hired').length) +\n      ' / ' + e(job.headcount || '1') + ' hired',\n    e(job.target_date || 'To confirm'),\n    tag(job.status,job.status === 'Open' ? 'good' : ''),\n    '<div class=\"row-actions\">'+btn('Manage','job',job.id)+ (job.profile==='client-acquisition-v1'?btn('Full job description','role-view'):'')+'</div>'\n  ]);\n  return heading('Recruitment management','Keep roles, next actions and hiring decisions moving.',\n    '<div class=\"toolbar\">' + btn('Export records','export') + btn('+ Open position','job','',true) + '</div>') +\n    '<div class=\"metrics\" aria-label=\"Current pipeline counts\">' + metrics + '</div>' +\n    panel('Hiring now','<p><strong>'+e(hiringRole.title)+'</strong></p><p class=\"muted\">Independent contractor · Remote · No fixed salary · 10% / 20% / 30% recurring commission</p>',btn('View role & terms','role-view','',true)) +\n    panel('Needs attention',queue.length ? candidateTable(queue.slice(0,5)) :\n      empty(active.length ? 'Every active candidate has a next step scheduled.' : 'Add your first candidate to build the action queue.'),\n      btn('View all actions','attention')) +\n    panel('Positions',jobRows.length ? table(['Role','Department / market','Headcount','Target date','Status','Action'],jobRows) :\n      empty('Open a position, define the role requirements, then add candidates.'),\n      tag(openJobs.length + ' open · ' + active.length + ' active candidates')) +\n    panel('Recent candidates',candidateTable(candidates.slice(0,6)),btn('+ Add candidate','candidate','',true));\n}\nfunction filteredCandidates() {\n  const group = groupStages.find(([name]) => 'group:' + name === stageFilter);\n  const query = search.trim().toLowerCase();\n  const list = state.candidates.filter(candidate => {\n    const stageMatch = !stageFilter || (group ? group[1].includes(candidate.stage) : candidate.stage === stageFilter);\n    const flag = attention(candidate);\n    return stageMatch && (!jobFilter || candidate.job_id === jobFilter) &&\n      (!ownerFilter || candidate.owner === ownerFilter) &&\n      (!attentionFilter || (attentionFilter === 'needs-action' ?\n        !['On track','Closed'].includes(flag) : flag === attentionFilter)) &&\n      (!query || [candidate.alias,candidate.source,candidate.owner,jobTitle(candidate.job_id)]\n        .some(value => String(value || '').toLowerCase().includes(query)));\n  });\n  if (sort === 'due') list.sort((a,b) => (a.due || '9999').localeCompare(b.due || '9999') || b.revision - a.revision);\n  if (sort === 'code') list.sort((a,b) => a.alias.localeCompare(b.alias,undefined,{numeric:true}));\n  return list;\n}\nfunction candidateResults() {\n  const list = filteredCandidates();\n  const pages = Math.max(1,Math.ceil(list.length / pageSize));\n  currentPage = Math.min(currentPage,pages);\n  const start = (currentPage - 1) * pageSize;\n  return '<p class=\"result-count\" role=\"status\">' + list.length + ' candidates · page ' + currentPage + ' of ' + pages + '</p>' +\n    candidateTable(list.slice(start,start + pageSize)) +\n    (pages > 1 ? '<div class=\"pagination\">' +\n      (currentPage > 1 ? btn('Previous','previous') : '') +\n      (currentPage < pages ? btn('Next','next') : '') + '</div>' : '');\n}\nfunction pipeline() {\n  return heading('Candidate pipeline','Filter by role, stage, owner or outstanding action.',\n    '<div class=\"toolbar\">' + btn('Export CSV','csv') + btn('+ Add candidate','candidate','',true) + '</div>') +\n    panel('Candidates','<div class=\"filters\">' +\n      '<label class=\"field\">Search<input id=\"search\" type=\"search\" maxlength=\"100\" placeholder=\"Candidate code, role or source\" value=\"' + e(search) + '\"></label>' +\n      '<label class=\"field\">Position<select id=\"job-filter\">' + options([['','All positions'],...state.jobs.map(job => [job.id,job.title])],jobFilter) + '</select></label>' +\n      '<label class=\"field\">Stage<select id=\"stage-filter\">' + options([['','All stages'],...groupStages.map(([name]) => ['group:' + name,name + ' group']),...stages],stageFilter) + '</select></label>' +\n      '<label class=\"field\">Action owner<select id=\"owner-filter\">' + options([['','All owners'],...owners],ownerFilter) + '</select></label>' +\n      '<label class=\"field\">Attention<select id=\"attention-filter\">' + options([['','All candidates'],['needs-action','Needs action'],'Overdue','Due today','Needs decision','Missing next step','Closed'],attentionFilter) + '</select></label>' +\n      '<label class=\"field\">Sort<select id=\"sort-filter\">' + options([['recent','Newest first'],['due','Due date'],['code','Candidate code']],sort) + '</select></label></div>' +\n      '<div id=\"candidate-results\">' + candidateResults() + '</div>',btn('Reset filters','reset'));\n}\nfunction activity() {\n  const daily = events.filter(event => event.event_date === reportDate).slice().reverse();\n  const summaries = daily.filter(event => event.kind === 'summary');\n  const entries = daily.filter(event => event.kind !== 'summary');\n  const aliases = new Map(state.candidates.map(candidate => [candidate.id,candidate.alias]));\n  const metrics = ['Candidate sourced','First outreach','R1 completed','R2 completed','Offer sent','Hired'];\n  return heading('Daily activity','Progress, decisions and next workday priorities in Sri Lanka time.',btn('+ Daily summary','summary','',true)) +\n    panel('Daily report','<div class=\"statline\">' + metrics.map(label => tag(label + ' · ' +\n      entries.filter(event => eventLabel(event) === label).length)).join('') + '</div>',\n      '<label class=\"field\">Report date (SL)<input type=\"date\" id=\"report-date\" value=\"' + e(reportDate) + '\"></label>') +\n    '<div class=\"split\">' + panel('COO updates',summaries.length ? '<ul class=\"timeline\">' + summaries.map(event =>\n      '<li><strong>Progress</strong><p>' + e(event.payload.progress) + '</p><strong>Blockers / decisions</strong><p>' +\n      e(event.payload.blockers || 'None recorded') + '</p><strong>Next priorities</strong><p>' + e(event.payload.priorities) +\n      '</p><time>' + e(new Date(event.created_at).toLocaleString('en-LK',{timeZone:'Asia/Colombo'})) + ' SL</time></li>').join('') +\n      '</ul>' : empty('No summary for this date. Add one to record the COO handover.')) +\n    panel('Event log',entries.length ? '<ul class=\"timeline\">' + entries.slice(0,100).map(event =>\n      '<li><strong>' + e(eventLabel(event)) + '</strong><p>' +\n      e(aliases.get(event.subject_id || event.id) || event.payload.title || '') +\n      (event.payload.note ? ' · ' + e(event.payload.note) : '') + '</p></li>').join('') + '</ul>' +\n      (entries.length > 100 ? '<p class=\"muted\">Showing the latest 100 events. Export records for the complete history.</p>' : '') :\n      empty('No activity recorded for this date.')) + '</div>';\n}\nfunction scheduledInterviews() {\n  return state.candidates.flatMap(candidate => {\n    const round = candidate.stage === 'R1 Scheduled' ? 'R1' : candidate.stage === 'R2 Scheduled' ? 'R2' : '';\n    const slot = round && candidate[round.toLowerCase()];\n    return slot ? [{candidate,round,slot}] : [];\n  }).sort((a,b) => a.slot.localeCompare(b.slot));\n}\nfunction interviews() {\n  const bookings = scheduledInterviews();\n  return heading('Interview calendar','Current bookings in Sri Lanka time. Reschedule or cancel through a candidate update.') +\n    panel('Scheduled interviews',bookings.length ? table(['Candidate','Position','Round','Sri Lanka time','Actions'],\n      bookings.map(({candidate,round,slot}) => [\n        '<strong>' + e(candidate.alias) + '</strong>',e(jobTitle(candidate.job_id)),tag(round,'blue'),\n        e(slot.replace('T',' ')) + (slot.slice(0,10) < dateSL() ? '<small>Past date · review the candidate stage</small>' : ''),\n        '<div class=\"row-actions\">' + btn('Calendar file','calendar',candidate.id) +\n          btn('Reschedule / cancel','stage',candidate.id,true) + '</div>'\n      ])) : empty('No scheduled interviews. Open a candidate, choose R1 Scheduled or R2 Scheduled and set a time.'));\n}\nconst relationsPrompts = [\n  ['Opening',3,'Confirm the role, commission or payment structure, client markets and the interview plan.'],\n  ['Prospect research',10,'Present six slides on one target account, their likely need, decision maker, outreach angle, follow-up plan and success measures.'],\n  ['Defence',10,'Explain the account choice, the evidence behind the proposed need, what AI suggestions you rejected, and the first metric you would track.'],\n  ['Client role-play',20,'Handle an unhappy client, an unrealistic promise request, a budget objection, a confidentiality request and an interruption. Agree a concrete next step.'],\n  ['Team behaviours',10,'Use four questions from the existing team behaviours question bank.'],\n  ['Candidate questions',5,'Discuss the role and ways of working.'],\n  ['Close',2,'Confirm references, outstanding checks and the decision timeline.']\n];\nfunction guideView() {\n  const original = (guideTrack==='Social media'?['R1','R2','Bank','Other']:['Bank','Other']).map(key => {\n    const title = {R1:'Screening · 30 min',R2:'Technical · 60 min',Bank:'Team behaviours',Other:'Scoring and workflow'}[key];\n    return '<section class=\"panel\"><details' + (key === 'R1' ? ' open' : '') + '><summary>' + title + '</summary>' +\n      guide.filter(([round]) => key === 'Other' ? !['R1','R2','Bank'].includes(round) : round === key)\n        .map(([,section,minutes,prompt,note]) => '<div class=\"guide-item\"><strong>' + e(section) +\n          (minutes ? ' · ' + minutes + ' min' : '') + '</strong><p>' + e(prompt) + '</p>' +\n          (note ? '<small>' + e(note) + '</small>' : '') + '</div>').join('') + '</details></section>';\n  }).join('');\n  return heading('Interview guide','Use consistent prompts and record observable evidence.',\n    '<label class=\"field\">Role track<select id=\"guide-track\">' + options(['Social media','Client Acquisition & Relations'],guideTrack) + '</select></label>') +\n    (guideTrack === 'Social media' ? original : panel('Client Acquisition & Relations · Screening',hiringRole.screening.map(([label,prompt])=>'<div class=\"guide-item\"><strong>'+e(label)+'</strong><p>'+e(prompt)+'</p></div>').join(''))+panel('Client Acquisition & Relations · Round 2',\n      '<p class=\"muted\">Use the screening and team behaviours prompts below, with this role-specific technical brief.</p>' +\n      relationsPrompts.map(([label,minutes,prompt]) => '<div class=\"guide-item\"><strong>' + e(label) + ' · ' + minutes +\n        ' min</strong><p>' + e(prompt) + '</p></div>').join('')) + original);\n}\nfunction render() {\n  const activeId = document.activeElement?.id;\n  const selection = activeId === 'search' ? [\n    document.activeElement.selectionStart,document.activeElement.selectionEnd\n  ] : null;\n  const view = page();\n  for (const link of document.querySelectorAll('#nav a')) {\n    const selected = link.hash === '#' + view;\n    link.classList.toggle('active',selected);\n    if (selected) link.setAttribute('aria-current','page');\n    else link.removeAttribute('aria-current');\n  }\n  const screens = {overview,coo:cooView,role:roleView,pipeline,activity,interviews,guide:guideView};\n  const draft = storageRead();\n  const draftBanner = draft ? '<div class=\"draft-banner\"><span>Unsaved ' + e(draft.kind) + ' draft available.</span>' +\n    '<div class=\"row-actions\">' + btn('Resume draft','resume') + btn('Discard draft','discard') + '</div></div>' : '';\n  const alert = failure ? '<p class=\"banner\" role=\"alert\">' + e(failure) +\n    ' Existing records remain visible. Use Refresh to retry.</p>' : '';\n  app.innerHTML = alert + draftBanner + (!ready && view !== 'guide' ?\n    panel('Recruitment workspace',empty(failure ? 'The shared records could not be loaded.' : 'Loading shared records…')) : screens[view]());\n  const active = activeId && document.getElementById(activeId);\n  if (active && app.contains(active)) {\n    active.focus({preventScroll:true});\n    if (selection) active.setSelectionRange(...selection);\n  }\n}\nfunction field(name,label,{kind = 'text',value = '',choices = [],required = false,max = 240,wide = false} = {}) {\n  const attributes = 'name=\"' + e(name) + '\"' + (required ? ' required' : '');\n  let input;\n  if (kind === 'select') input = '<select ' + attributes + '>' + options(choices,value) + '</select>';\n  else if (kind === 'textarea') input = '<textarea ' + attributes + ' maxlength=\"' + max + '\">' + e(value) + '</textarea>';\n  else input = '<input type=\"' + e(kind) + '\" ' + attributes + ' value=\"' + e(value) + '\"' +\n    (kind === 'text' ? ' maxlength=\"' + max + '\"' : '') + (kind === 'number' ? ' min=\"1\" max=\"999\" step=\"1\"' : '') + '>';\n  return '<label class=\"field' + (wide ? ' wide' : '') + '\">' + e(label) +\n    (required ? ' <span class=\"required\" aria-hidden=\"true\">*</span>' : '') + input + '</label>';\n}\nconst select = (name,label,choices,value) => field(name,label,{kind:'select',choices,value,required:true});\nconst notes = (name,label,required = false,value = '') => field(name,label,{kind:'textarea',wide:true,required,max:600,value});\nconst roundFields = {R1:['Acquisition evidence','Client communication','Commercial judgment','Confidentiality & terms'],R2:['Prospect research','Discovery & proposals','Objection handling','Client relations & follow-up']};\nfunction show(html) {\n  focusReturn = document.activeElement;\n  dialog.innerHTML = html;\n  if (!dialog.open) dialog.showModal();\n  dialog.scrollTop = 0;\n}\nfunction showRecord(candidate) {\n  const checklist = checklistItems.map(([key,label]) =>\n    '<li><span>' + e(label) + '</span>' + tag(candidate.checklist[key] || 'Pending',\n      candidate.checklist[key] === 'Complete' ? 'good' : '') + '</li>').join('');\n  const history = candidate.history.slice().reverse().map(event => {\n    const labels = {score1:'Criterion 1',score2:'Criterion 2',score3:'Criterion 3',score4:'Criterion 4'};\n    const text = Object.entries(event.payload).filter(([key,value]) => value && key !== 'job_id')\n      .map(([key,value]) => (labels[key] || key.replaceAll('_',' ')) + ' · ' + value).join('\\n');\n    return '<li><strong>' + e(eventLabel(event)) + '</strong> <time>' + e(event.event_date) +\n      '</time><p class=\"snapshot\">' + e(text) + '</p></li>';\n  }).join('');\n  show('<div class=\"section-top\"><h2 id=\"dialog-title\">' + e(candidate.alias) + '</h2>' + btn('Close','close') +\n    '</div><p class=\"muted\">' + e(jobTitle(candidate.job_id)) + ' · ' + e(candidate.stage) + '</p>' +\n    '<p class=\"muted\">Availability · ' + e(candidate.availability || 'To confirm') + ' · Notice · ' +\n    e(candidate.notice || 'To confirm') + '</p><div class=\"toolbar\">' +\n    btn('Update stage / schedule','stage',candidate.id,true) + btn('Log milestone','activity',candidate.id) +\n    btn('Scorecard','score',candidate.id) + btn('Hiring checklist','checklist',candidate.id) + btn('CV & cover letter','documents',candidate.id) + btn('Commission review','commission',candidate.id) +\n    '</div><p class=\"public-note\">Commission-only acknowledgement: '+e(candidate.commission_ack||'Not recorded')+' · CV: '+e(candidate.documents?.cv||'Missing')+' · Cover letter: '+e(candidate.documents?.cover||'Missing')+'</p><h3>Hiring readiness</h3><ul class=\"checklist\">' + checklist +\n    '</ul><h3>Record history</h3><ul class=\"timeline\">' + history + '</ul>');\n}\nfunction openForm(kind,id = '',restored = null) {\n  const existingDraft = storageRead();\n  if (!restored && existingDraft) {\n    const same = existingDraft.kind === kind && existingDraft.id === id;\n    if (same) return openForm(kind,id,existingDraft);\n    flash('Resume or discard the existing draft before starting another entry.');\n    if (dialog.open) dialog.close();\n    render();\n    return;\n  }\n  const candidate = candidateById(id);\n  const job = state.jobs.find(item => item.id === id);\n  const openJobs = state.jobs.filter(item => item.status === 'Open');\n  if (kind === 'candidate' && !openJobs.length) {\n    flash('Open a position before adding a candidate.');\n    return;\n  }\n  const required = {required:true};\n  const next = (value = {}) => '<fieldset class=\"form-grid wide\" id=\"next-fields\"><legend>Next action</legend>' +\n    field('action','Next step',{...required,value:value.action}) +\n    field('due','Due date (SL)',{...required,kind:'date',value:value.due}) +\n    select('owner','Owner',[['','Choose owner'],...owners],value.owner) +\n    field('blocker','Blocker / decision needed',{value:value.blocker}) + '</fieldset>';\n  let title;\n  let fields;\n  if (kind === 'job') {\n    title = job ? 'Manage position' : 'Open a position';\n    fields = field('title','Job title',{...required,value:job?.title}) +\n      field('department','Department',{...required,value:job?.department || 'Client Services'}) +\n      field('location','Location / market',{...required,value:job?.location || 'Sri Lanka · Remote'}) +\n      select('employment','Engagement type',employmentTypes,job?.employment || 'Contract') +\n      field('headcount','Target headcount',{...required,kind:'number',value:job?.headcount || '1'}) +\n      field('target_date','Target hiring date',{kind:'date',value:job?.target_date}) +\n      notes('brief','Role requirements / success criteria',true,job?.brief || '') +\n      (job ? select('status','Position status',['Open','Paused','Closed'],job.status) + notes('note','Reason for update',true) : '');\n  } else if (kind === 'candidate') {\n    title = 'Add a candidate';\n    fields = field('alias','Unique candidate code',{...required,max:40}) +\n      select('job_id','Position',openJobs.map(item => [item.id,item.title]),openJobs[0].id) +\n      select('source','Source',sources,sources[0]) +\n      select('availability','Availability',['To confirm','Available now','Within 2 weeks','Within 1 month','Later'], 'To confirm') +\n      field('notice','Notice period',{...required,value:'To confirm'}) + field('market','Target client markets',{value:'To confirm'}) + select('commission_plan','Commission structure',['10 / 20 / 30 recurring','Other agreed terms'],'10 / 20 / 30 recurring') + select('commission_ack','Candidate accepts commission-only terms',['Pending','Accepted','Declined'],'Pending') + '<p class=\"hint wide\">Save the candidate code first, then open CV & cover letter to enter their private name and upload the application documents. Real names are kept out of the public record.</p>' + next();\n  } else if (kind === 'stage' && candidate) {\n    title = 'Update · ' + candidate.alias;\n    fields = select('stage','Stage',stages,candidate.stage) + next(candidate) +\n      field('r1','R1 interview (Sri Lanka time)',{kind:'datetime-local',value:candidate.r1}) +\n      field('r2','R2 interview (Sri Lanka time)',{kind:'datetime-local',value:candidate.r2}) +\n      '<div class=\"wide\" id=\"start-field\">' + field('start_date','Confirmed start date',{kind:'date',value:candidate.start_date}) + '</div>' +\n      notes('note','Reason / decision summary',true) +\n      '<p class=\"hint wide\">To cancel a booking, clear its time and select the next stage. Previous bookings stay in history. Complete the hiring checklist before marking Hired.</p>';\n  } else if (kind === 'checklist' && candidate) {\n    title = 'Hiring checklist · ' + candidate.alias;\n    fields = checklistItems.map(([key,label]) => select(key,label,['Pending','Complete','Waived'],\n      candidate.checklist[key] || 'Pending')).join('') +\n      notes('note','Evidence summary / reasons for any waiver',true);\n  } else if (kind === 'activity' && candidate) {\n    title = 'Log milestone · ' + candidate.alias;\n    fields = select('event','Milestone',milestones,milestones[0]) + notes('note','Public progress summary',true);\n  } else if (kind === 'score' && candidate) {\n    title = 'Scorecard · ' + candidate.alias;\n    fields = select('round','Round',['R1','R2'],'R1') +\n      select('reviewer','Reviewer role',['COO','Leadership'],'COO') +\n      select('recommendation','Recommendation',['Advance','Hold','Reject'],'Advance') +\n      '<div class=\"form-grid wide\" id=\"round-fields\"></div>' + notes('note','Observable evidence',true);\n  } else if (kind === 'commission' && candidate) {\n    title='Commission review · '+candidate.alias;\n    fields=select('commission_plan','Agreed structure',['10 / 20 / 30 recurring','Other agreed terms'],candidate.commission_plan||'10 / 20 / 30 recurring')+select('commission_ack','Candidate acknowledgement',['Pending','Accepted','Declined'],candidate.commission_ack||'Pending')+notes('note','Terms explained / next action (public-safe)',true);\n  } else if (kind === 'summary') {\n    title = 'Daily COO summary';\n    fields = notes('progress','Progress today',true) + notes('blockers','Blockers / leadership decisions') +\n      notes('priorities','Next workday priorities',true);\n  } else return;\n  const revision = restored?.revision ?? candidate?.revision ?? job?.revision ?? 0;\n  show('<form id=\"entry\" data-kind=\"' + e(kind) + '\" data-id=\"' + e(id) +\n    '\" data-request=\"' + e(restored?.request || newId()) + '\" data-revision=\"' + revision +\n    '\"><div class=\"section-top\"><h2 id=\"dialog-title\">' + e(title) + '</h2>' + btn('Close','close') +\n    '</div><p class=\"public-note\">Public workspace. Use candidate codes and public-safe notes. Fields marked * are required.</p>' +\n    '<div class=\"form-grid\">' + field('event_date','Event date (SL)',{kind:'date',required:true,\n      value:kind === 'summary' ? reportDate : dateSL()}) + fields + '</div>' +\n    '<p class=\"form-error\" role=\"alert\"></p><div class=\"form-actions\">' + btn('Discard draft','discard') +\n    '<button class=\"btn primary\" type=\"submit\">Save record</button></div></form>');\n  pendingRecord = restored?.pending || null;\n  if (kind === 'score') setRoundFields(restored?.values?.round || 'R1');\n  if (restored?.values) {\n    for (const [key,value] of Object.entries(restored.values)) {\n      const input = dialog.querySelector('[name=\"' + key + '\"]');\n      if (input) input.value = value;\n    }\n  }\n  updateStageFields();\n  if (pendingRecord) freezePending();\n  dialog.querySelector('input,select,textarea')?.focus();\n}\nfunction setRoundFields(round) {\n  dialog.querySelector('#round-fields').innerHTML = roundFields[round].map((label,i) =>\n    field('score' + (i + 1),label,{kind:'select',choices:[['','Untested'],'1','2','3','4','5']})).join('');\n}\nfunction updateStageFields() {\n  const stage = dialog.querySelector('[name=\"stage\"]')?.value;\n  if (!stage) return;\n  dialog.querySelector('#next-fields').disabled = closed.includes(stage);\n  const start = dialog.querySelector('#start-field');\n  start.hidden = stage !== 'Hired';\n  start.querySelector('input').required = stage === 'Hired';\n  for (const round of ['r1','r2']) {\n    dialog.querySelector('[name=\"' + round + '\"]').required = stage === (round === 'r1' ? 'R1 Scheduled' : 'R2 Scheduled');\n  }\n}\nfunction draftValues(form) {\n  const result = {};\n  for (const input of form.querySelectorAll('[name]')) result[input.name] = input.value;\n  return result;\n}\nfunction saveDraft() {\n  const form = dialog.querySelector('#entry');\n  if (!form) return;\n  storageWrite({\n    kind:form.dataset.kind,id:form.dataset.id,request:form.dataset.request,\n    revision:Number(form.dataset.revision),values:draftValues(form),pending:pendingRecord\n  });\n}\nfunction freezePending() {\n  for (const input of dialog.querySelectorAll('input,select,textarea')) input.disabled = true;\n  const submit = dialog.querySelector('[type=\"submit\"]');\n  submit.textContent = 'Retry same save';\n}\nfunction flash(text) {\n  notice.textContent = text;\n  clearTimeout(noticeTimer);\n  noticeTimer = setTimeout(() => { notice.textContent = '' },6000);\n}\nfunction download(name,content,type) {\n  const url = URL.createObjectURL(new Blob([content],{type}));\n  const anchor = document.createElement('a');\n  anchor.href = url;\n  anchor.download = name;\n  anchor.click();\n  setTimeout(() => URL.revokeObjectURL(url),1000);\n}\nfunction calendar(candidate) {\n  const round = candidate.stage === 'R1 Scheduled' ? 'R1' : 'R2';\n  const slot = candidate[round.toLowerCase()];\n  if (!slot) return;\n  const start = new Date(slot + ':00+05:30');\n  const end = new Date(+start + (round === 'R1' ? 30 : 60) * 60000);\n  const stamp = date => date.toISOString().replace(/[-:]/g,'').slice(0,15) + 'Z';\n  const safe = value => String(value).replaceAll('\\\\','\\\\\\\\').replaceAll(';','\\\\;').replaceAll(',','\\\\,').replace(/\\r?\\n/g,'\\\\n');\n  const content = ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//QuidEdge//Recruitment//EN','BEGIN:VEVENT',\n    'UID:' + candidate.id + '-' + round + '@quidedge','DTSTAMP:' + stamp(new Date()),\n    'DTSTART:' + stamp(start),'DTEND:' + stamp(end),'SUMMARY:' + safe(candidate.alias + ' ' + round + ' interview'),\n    'DESCRIPTION:' + safe(jobTitle(candidate.job_id)),'END:VEVENT','END:VCALENDAR',''].join('\\r\\n');\n  download(candidate.alias + '-' + round + '.ics',content,'text/calendar;charset=utf-8');\n}\nasync function refresh() {\n  if (refreshing || saving || !navigator.onLine) return;\n  refreshing = true;\n  sync.disabled = true;\n  try {\n    const cursor = events.at(-1)?.seq || 0;\n    const incoming = await loadEvents(cursor);\n    const changed = ingest(incoming);\n    const hadFailure = Boolean(failure);\n    failure = '';\n    const initial = !ready;\n    ready = true;\n    mode.textContent = 'Synced · ' + new Date().toLocaleTimeString('en-LK',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Colombo'}) + ' SL';\n    sync.className = 'pill live';\n    if (changed || initial || hadFailure) render();\n  } catch (error) {\n    failure = error.message;\n    mode.textContent = 'Retry sync';\n    sync.className = 'pill error';\n    render();\n  } finally {\n    refreshing = false;\n    sync.disabled = false;\n  }\n}\nfunction resetFilters() {\n  stageFilter = '';jobFilter = '';ownerFilter = '';attentionFilter = '';search = '';currentPage = 1;\n}\napp.addEventListener('input',event => {\n  if (event.target.id !== 'search') return;\n  search = event.target.value;\n  currentPage = 1;\n  clearTimeout(searchTimer);\n  searchTimer = setTimeout(() => {\n    const result = app.querySelector('#candidate-results');\n    if (result) result.innerHTML = candidateResults();\n  },120);\n});\napp.addEventListener('change',event => {\n  const value = event.target.value;\n  const key = event.target.id;\n  if (key === 'report-date' && value) reportDate = value;\n  if (key === 'stage-filter') stageFilter = value;\n  if (key === 'job-filter') jobFilter = value;\n  if (key === 'attention-filter') attentionFilter = value;\n  if (key === 'owner-filter') ownerFilter = value;\n  if (key === 'sort-filter') sort = value;\n  if (key === 'guide-track') guideTrack = value;\n  currentPage = 1;\n  render();\n});\ndocument.addEventListener('click',event => {\n  if (event.target.closest('.skip')) {\n    event.preventDefault();\n    app.focus();\n    return;\n  }\n  const control = event.target.closest('[data-action]');\n  if (!control || saving) return;\n  const {action,id} = control.dataset;\n  if (action === 'close') { saveDraft();dialog.close();render();return }\n  if (action === 'discard') { storageWrite(null);pendingRecord = null;dialog.close();render();return }\n  if (action === 'resume') {\n    const draft = storageRead();\n    if (draft) openForm(draft.kind,draft.id,draft);\n    return;\n  }\n  if (action === 'group' || action === 'attention') {\n    resetFilters();\n    if (action === 'group') stageFilter = 'group:' + id;\n    else attentionFilter = 'needs-action';\n    location.hash = 'pipeline';\n    render();\n    return;\n  }\n  if (action === 'reset') { resetFilters();render();return }\n  if (action === 'next' || action === 'previous') {\n    currentPage += action === 'next' ? 1 : -1;\n    render();\n    return;\n  }\n  if (action === 'view') {\n    const candidate = candidateById(id);\n    if (candidate) showRecord(candidate);\n    return;\n  }\n  if (action === 'role-view') {location.hash='role';render();return;}\n  if (action === 'activate-role') {activateRole();return;}\n  if (action === 'documents') {showDocuments(candidateById(id));return;}\n  if (action === 'calendar') { calendar(candidateById(id));return }\n  if (action === 'export') {\n    download('QuidEdge-records-' + dateSL() + '.json',\n      JSON.stringify({exported_at:new Date().toISOString(),events},null,2),'application/json');\n    return;\n  }\n  if (action === 'csv') {\n    const rows = [['Code','Position','Stage','Owner','Next action','Due','Attention']];\n    for (const candidate of filteredCandidates()) rows.push([\n      candidate.alias,jobTitle(candidate.job_id),candidate.stage,candidate.owner,candidate.action,candidate.due,attention(candidate)\n    ]);\n    download('QuidEdge-candidates-' + dateSL() + '.csv',rows.map(row => row.map(csvCell).join(',')).join('\\r\\n'),'text/csv;charset=utf-8');\n    return;\n  }\n  openForm(action,id);\n});\ndialog.addEventListener('input',saveDraft);\ndialog.addEventListener('change',event => {\n  if (event.target.name === 'stage') updateStageFields();\n  if (event.target.name === 'round') setRoundFields(event.target.value);\n  if (event.target.name === 'event' && event.target.value==='Commission terms reviewed') {openForm('commission',event.target.form.dataset.id);return;}\n  saveDraft();\n});\ndialog.addEventListener('cancel',event => {\n  if (saving) event.preventDefault();\n  else saveDraft();\n});\ndialog.addEventListener('close',() => {\n  if (!saving) render();\n  if (focusReturn?.isConnected) focusReturn.focus();\n});\ndialog.addEventListener('submit',async event => {\n  if(event.target.id==='document-entry'){event.preventDefault();saveDocuments(event.target);return;}\n  if (event.target.id !== 'entry') return;\n  event.preventDefault();\n  if (saving) return;\n  const form = event.target;\n  const errorBox = form.querySelector('.form-error');\n  const {kind,id} = form.dataset;\n  let record = pendingRecord;\n  if (!record) {\n    const values = Object.fromEntries([...new FormData(form)].map(([key,value]) => [key,value.trim()]));\n    const eventDate = values.event_date;\n    delete values.event_date;\n    if (kind === 'candidate') values.stage = 'Sourced';\n    if (kind === 'job' && id) values.job_id = id;\n    if (kind === 'commission') values.event='Commission terms reviewed';\n    if (kind === 'checklist') values.event = 'Hiring checklist updated';\n    if (kind === 'stage') {\n      if (closed.includes(values.stage)) Object.assign(values,{action:'',due:'',owner:'',blocker:''});\n      const problem = stageProblem(values,candidateById(id),eventDate);\n      if (problem) { errorBox.textContent = problem;return }\n    }\n    record = {\n      id:form.dataset.request,kind:['checklist','commission'].includes(kind) ? 'activity' : kind,\n      subject_id:kind === 'job' ? null : id || null,event_date:eventDate,payload:values\n    };\n    if (id) record.expected_seq = Number(form.dataset.revision);\n  }\n  pendingRecord = record;\n  saveDraft();\n  saving = true;\n  const controls = form.querySelectorAll('button,input,select,textarea');\n  for (const input of controls) input.disabled = true;\n  const submit = form.querySelector('[type=\"submit\"]');\n  submit.textContent = 'Saving…';\n  errorBox.textContent = '';\n  try {\n    const saved = await append(record);\n    ingest([saved]);\n    pendingRecord = null;\n    storageWrite(null);\n    if (kind === 'summary') reportDate = record.event_date;\n    dialog.close();\n    render();\n    flash('Saved to the shared workspace. The original history is preserved.');\n  } catch (error) {\n    errorBox.textContent = error.message;\n    if (error.status && error.status < 500) {\n      pendingRecord = null;\n      form.dataset.request = newId();\n      if (error.status === 409) {\n        saving = false;\n        await refresh();\n        const current = candidateById(id) || state.jobs.find(job => job.id === id);\n        if (current) {\n          form.dataset.revision = current.revision;\n          errorBox.textContent += ' Latest saved status: ' + (current.stage || current.status) +\n            '. Next action: ' + (current.action || 'None') + '. Review before saving again.';\n        }\n      }\n      for (const input of controls) input.disabled = false;\n      updateStageFields();\n      submit.textContent = 'Save record';\n      saveDraft();\n    } else {\n      for (const button of form.querySelectorAll('button')) button.disabled = false;\n      freezePending();\n      saveDraft();\n    }\n  } finally {\n    saving = false;\n  }\n});\nsync.addEventListener('click',refresh);\nwindow.addEventListener('hashchange',() => { render();app.focus({preventScroll:true}) });\nwindow.addEventListener('online',refresh);\nwindow.addEventListener('offline',() => { mode.textContent = 'Offline · draft kept';sync.className = 'pill error' });\ndocument.addEventListener('visibilitychange',() => { if (!document.hidden && !dialog.open) refresh() });\nwindow.addEventListener('pagehide',() => { saveDraft();clearInterval(timer) });\nrender();\nrefresh();\ntimer = setInterval(() => { if (!document.hidden && !dialog.open) refresh() },45000);\n\nfunction roleView() {\n  const r=hiringRole, active=state.jobs.some(j=>j.id===r.id);\n  return heading(r.title,'QuidEdge · Client Services · Remote',active?tag('Position added','good'):btn('Add this hiring position','activate-role','',true))+\n    panel('Commission-only opportunity','<p class=\"commission-lead\">No fixed salary</p><p>'+e(r.compensation)+'</p><p>'+e(r.important)+'</p><div class=\"commission-grid\">'+r.tiers.map(([rate,range])=>'<div><strong>'+e(rate)+'</strong><span>'+e(range)+'</span></div>').join('')+'</div><p>'+e(r.payment)+'</p><p class=\"hint\">'+e(r.boundary)+'</p>')+\n    panel('Role details',table(['Company','Location','Engagement','Industry'],[[e(r.company),e(r.location),e(r.employment),e(r.industry)]]))+\n    '<div class=\"split\">'+panel('About QuidEdge',r.about.map(p=>'<p>'+e(p)+'</p>').join(''))+panel('About the role',r.overview.map(p=>'<p>'+e(p)+'</p>').join(''))+'</div>'+\n    panel('Key responsibilities','<ol class=\"role-list\">'+r.responsibilities.map(p=>'<li>'+e(p)+'</li>').join('')+'</ol>')+\n    panel('Why join QuidEdge?','<div class=\"benefit-grid\">'+r.benefits.map(([title,text])=>'<article><h3>'+e(title)+'</h3><p>'+e(text)+'</p></article>').join('')+'</div>');\n}\nasync function activateRole() {\n  if(saving)return; saving=true;\n  try {const saved=await append(defaultRoleRecord(dateSL()));ingest([saved]);render();flash('Client Acquisition & Client Relations position added.');}\n  catch(err){flash(err.message);}finally{saving=false;}\n}\nfunction cooView() {\n  const relatedJobs=state.jobs.filter(j=>j.profile==='client-acquisition-v1'||j.id===hiringRole.id);\n  const ids=new Set(relatedJobs.map(j=>j.id));\n  const candidates=state.candidates.filter(c=>ids.has(c.job_id));\n  const active=candidates.filter(c=>!closed.includes(c.stage));\n  const due=active.filter(c=>c.due && c.due<=dateSL()).sort((a,b)=>a.due.localeCompare(b.due));\n  const documents=active.filter(c=>c.documents?.cv!=='Uploaded'||c.documents?.cover!=='Uploaded');\n  const terms=active.filter(c=>c.commission_ack!=='Accepted');\n  const review=active.filter(c=>['R1 Review','R2 Review','Reference Check','Offer / Agreement'].includes(c.stage));\n  const stats=[['Active candidates',active.length],['Due / overdue',due.length],['Documents incomplete',documents.length],['Terms to confirm',terms.length]];\n  const summaries=events.filter(x=>x.kind==='summary'&&x.event_date===dateSL());\n  return heading('COO recruitment workspace','Client Acquisition & Client Relations · Daily priorities and review queue',\n    '<div class=\"toolbar\">'+btn('Role & commission terms','role-view')+btn('+ Add candidate','candidate','',true)+'</div>')+\n    '<div class=\"coo-stats\">'+stats.map(([title,total])=>'<div class=\"panel\"><span>'+e(title)+'</span><strong>'+total+'</strong></div>').join('')+'</div>'+\n    panel('Today’s next actions',candidateTable(due))+\n    '<div class=\"split\">'+panel('Ready for COO review',candidateTable(review))+panel('Commission acknowledgement',candidateTable(terms))+'</div>'+\n    panel('CV & cover letter checklist',documents.length?table(['Candidate','CV','Cover letter','Action'],documents.map(c=>[\n      '<strong>'+e(c.alias)+'</strong>',tag(c.documents?.cv||'Missing',c.documents?.cv==='Uploaded'?'good':'warn'),\n      tag(c.documents?.cover||'Missing',c.documents?.cover==='Uploaded'?'good':'warn'),btn('Upload / view documents','documents',c.id,true)\n    ])):empty(active.length?'All active candidates have both application documents.':'No candidates added yet. Upload status will appear here.'))+\n    panel('Daily COO handover',summaries.length?'<p>'+e(summaries.at(-1).payload.progress)+'</p><p><strong>Next priorities:</strong> '+e(summaries.at(-1).payload.priorities)+'</p>':empty('Add today’s progress, blockers and next priorities.'),btn('+ Daily summary','summary','',true))+\n    panel('Private application files','<p>Candidate names, CVs and cover letters belong in the restricted recruitment Drive folder. This public workspace displays candidate codes and upload status.</p><a class=\"btn\" target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://drive.google.com/drive/folders/'+driveRoot+'\">Open recruitment Drive folder</a>');\n}\nfunction showDocuments(candidate) {\n  if(!candidate)return;\n  const job=state.jobs.find(j=>j.id===candidate.job_id);\n  if(job?.profile!=='client-acquisition-v1'){flash('Use the Client Acquisition & Client Relations position for this upload workflow.');return;}\n  const stateMarkup='<div class=\"statline\">'+tag('CV: '+(candidate.documents?.cv||'Missing'))+tag('Cover letter: '+(candidate.documents?.cover||'Missing'))+'</div>';\n  show('<div class=\"section-top\"><h2 id=\"dialog-title\">Application documents · '+e(candidate.alias)+'</h2>'+btn('Close','close')+'</div>'+stateMarkup+\n    '<p class=\"public-note\">The full name and document contents go to Google Drive. They are not saved to the public candidate record or browser draft.</p>'+\n    '<p id=\"drive-connection\" class=\"hint\" role=\"status\">Checking Google Drive connection…</p>'+\n    '<form id=\"document-entry\" data-candidate=\"'+e(candidate.id)+'\"><div class=\"form-grid\">'+\n    field('private_name','Candidate’s full name (private)',{required:true,max:120,wide:true})+\n    '<label class=\"field\">CV<input type=\"file\" name=\"cv\" accept=\".pdf,.doc,.docx\"></label><label class=\"field\">Cover letter<input type=\"file\" name=\"cover\" accept=\".pdf,.doc,.docx\"></label></div>'+\n    '<p class=\"hint\">PDF, DOC or DOCX · up to 5 MB per file. New versions are preserved; identical retries reuse the existing file.</p>'+\n    '<p id=\"upload-progress\" role=\"status\"></p><p class=\"form-error\" role=\"alert\"></p><div class=\"form-actions\"><button class=\"btn primary\" type=\"submit\" disabled>Upload to Google Drive</button></div></form>'+\n    '<p><a class=\"btn\" href=\"'+e(privateFolderSearch(candidate.alias))+'\" target=\"_blank\" rel=\"noopener noreferrer\">Find candidate’s private Drive folder</a></p>');\n  const form=dialog.querySelector('#document-entry');\n  form.dataset.cvRequest=newId();form.dataset.coverRequest=newId();\n  fetch(apiBase+'/integrations',{cache:'no-store',signal:AbortSignal.timeout(10000)}).then(async response=>{\n    if(!response.ok)throw new Error('Connection check failed.');\n    const status=await response.json(); if(!form.isConnected)return;\n    const text=dialog.querySelector('#drive-connection');\n    text.textContent=status.drive_ready?'Google Drive connected. A separate named folder is created automatically for this candidate.':'Owner setup required: Google Drive uploads are not connected yet. Candidate records and the hiring workflow remain available.';\n    form.querySelector('[type=submit]').disabled=!status.drive_ready;\n  }).catch(()=>{if(form.isConnected)dialog.querySelector('#drive-connection').textContent='Could not check Drive. Close and reopen this panel to retry.';});\n}\nasync function saveDocuments(form) {\n  if(saving)return;\n  const errorBox=form.querySelector('.form-error'),progress=form.querySelector('#upload-progress');errorBox.textContent='';\n  const candidate=candidateById(form.dataset.candidate), name=form.elements.private_name.value.trim();\n  const tasks=['cv','cover'].map(type=>({type,file:form.elements[type].files[0]})).filter(t=>t.file);\n  if(name.length<2){errorBox.textContent='Enter the candidate’s full name.';return;}\n  if(!tasks.length){errorBox.textContent='Choose a CV, cover letter, or both.';return;}\n  try{for(const task of tasks)await checkDocument(task.file);}catch(err){errorBox.textContent=err.message;return;}\n  if(saving)return;\n  saving=true;const controls=dialog.querySelectorAll('button,input');for(const el of controls)el.disabled=true;\n  try {\n    for(const task of tasks){\n      progress.textContent='Uploading '+(task.type==='cv'?'CV':'cover letter')+'…';\n      const result=await uploadDocument(apiBase,candidate,name,task.file,task.type,form.dataset[task.type+'Request']);\n      ingest([result.event]);form.elements[task.type].value='';form.dataset[task.type+'Request']=newId();\n    }\n    progress.textContent='Saved to Google Drive. Original files are preserved.';\n    form.elements.private_name.value='';render();flash('Application documents saved to the candidate’s private Drive folder.');\n  } catch(err){errorBox.textContent=err.message;progress.textContent='Completed files remain saved. Retry the remaining selected document.';}\n  finally{saving=false;for(const el of controls)el.disabled=false;}\n}\n","type":"application/javascript; charset=utf-8"},"/model.js":{"body":"export const stages = ['Sourced','Contacted','Replied','R1 Scheduled','R1 Review','R2 Prep','R2 Scheduled','R2 Review','Reference Check','Offer / Agreement','On Hold','Hired','Rejected','Withdrawn'];\nexport const closed = ['Hired','Rejected','Withdrawn'];\nexport const milestones = ['First outreach','Reply received','Follow-up sent','R1 completed','R2 brief sent','R2 completed','Writing task completed','References completed','Offer sent','Agreement / NDA signed','Interview no-show','Interview cancelled','Offer declined','Blocker update','Commission terms reviewed'];\nexport const checklistItems = [\n  ['terms','Role and payment terms confirmed'],\n  ['writing','Writing / practical task reviewed'],\n  ['references','References checked'],\n  ['offer','Offer accepted'],\n  ['agreement','Agreement completed'],\n  ['nda','NDA completed']\n];\nexport const dateSL = (date = new Date()) => new Intl.DateTimeFormat('en-CA', {\n  timeZone:'Asia/Colombo',year:'numeric',month:'2-digit',day:'2-digit'\n}).format(date);\nexport const groupStages = [\n  ['Sourced',['Sourced','Contacted','Replied'],'amber'],\n  ['Screening',['R1 Scheduled','R1 Review'],'blue'],\n  ['Technical',['R2 Prep','R2 Scheduled','R2 Review','Reference Check'],'coral'],\n  ['Offer',['Offer / Agreement'],'purple'],\n  ['Hired',['Hired'],'green']\n];\nexport const escape = value => String(value ?? '').replace(/[&<>\"']/g, c => ({\n  '&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'\n}[c]));\nexport function validDate(value) {\n  if (typeof value !== 'string' || !/^\\d{4}-\\d{2}-\\d{2}$/.test(value)) return false;\n  const parsed = new Date(value + 'T00:00:00Z');\n  return Number.isFinite(+parsed) && parsed.toISOString().slice(0,10) === value;\n}\nexport function stageProblem(payload, candidate, eventDate) {\n  if (payload.stage === 'R1 Scheduled' && candidate.commission_ack && candidate.commission_ack !== 'Accepted') return 'Confirm that the candidate accepts the commission-only terms before scheduling Round 1.';\n  if (!stages.includes(payload.stage)) return 'Choose a valid stage.';\n  if (!String(payload.note || '').trim()) return 'Add the reason for this update.';\n  if (!closed.includes(payload.stage)) {\n    if (![payload.action,payload.due,payload.owner].every(Boolean)) return 'Set the next action, owner and due date.';\n  }\n  const slot = payload.stage === 'R1 Scheduled' ? payload.r1 : payload.stage === 'R2 Scheduled' ? payload.r2 : '';\n  if (['R1 Scheduled','R2 Scheduled'].includes(payload.stage)) {\n    if (!slot) return 'Set the interview date and time in Sri Lanka time.';\n    if (slot.slice(0,10) < eventDate) return 'The interview cannot be earlier than the event date.';\n  }\n  if (payload.stage === 'Hired') {\n    const missing = checklistItems.filter(([key]) => !['Complete','Waived'].includes(candidate.checklist[key]));\n    if (missing.length) return 'Complete or waive each hiring checklist item before marking Hired.';\n    if (!validDate(payload.start_date)) return 'Confirm the start date before marking Hired.';\n  }\n  return '';\n}\nexport function project(events) {\n  const jobs = new Map();\n  const candidates = new Map();\n  for (const event of [...events].sort((a,b) => a.seq - b.seq)) {\n    const p = event.payload;\n    if (event.kind === 'job') {\n      if (p.job_id) {\n        const job = jobs.get(p.job_id);\n        if (job) Object.assign(job,p,{id:p.job_id,revision:event.seq});\n      } else {\n        jobs.set(event.id,{status:'Open',headcount:'1',...p,id:event.id,revision:event.seq});\n      }\n    }\n    if (event.kind === 'candidate') {\n      candidates.set(event.id, {\n        ...p,id:event.id,date:event.event_date,revision:event.seq,\n        history:[event],r1:'',r2:'',checklist:{},documents:{cv:'Missing',cover:'Missing'},start_date:''\n      });\n    }\n    const candidate = candidates.get(event.subject_id);\n    if (!candidate) continue;\n    candidate.history.push(event);\n    candidate.revision = event.seq;\n    if (event.kind === 'stage') {\n      for (const key of ['stage','action','due','owner','blocker','r1','r2','start_date']) {\n        if (key in p) candidate[key] = p[key];\n      }\n    }\n    if (event.kind === 'activity') {\n      if (p.event === 'Document stored' && ['cv','cover'].includes(p.document_type)) candidate.documents[p.document_type] = 'Uploaded';\n      if (p.event === 'Commission terms reviewed') { candidate.commission_ack=p.commission_ack; candidate.commission_plan=p.commission_plan; }\n      if (p.event === 'Hiring checklist updated') {\n        for (const [key] of checklistItems) {\n          if (key in p) candidate.checklist[key] = p[key];\n        }\n      }\n      const completed = {\n        'Writing task completed':['writing'],\n        'References completed':['references'],\n        'Agreement / NDA signed':['agreement','nda']\n      }[p.event] || [];\n      for (const key of completed) candidate.checklist[key] = 'Complete';\n    }\n  }\n  return {jobs:[...jobs.values()].reverse(),candidates:[...candidates.values()].reverse()};\n}\nexport function attention(candidate, today = dateSL()) {\n  if (closed.includes(candidate.stage)) return 'Closed';\n  if (candidate.due && candidate.due < today) return 'Overdue';\n  if (candidate.blocker || candidate.owner === 'Leadership') return 'Needs decision';\n  if (!candidate.action || !candidate.due || !candidate.owner) return 'Missing next step';\n  return candidate.due === today ? 'Due today' : 'On track';\n}\nexport function csvCell(value) {\n  let text = String(value ?? '');\n  if (/^[\\s]*[=+@-]/.test(text)) text = \"'\" + text;\n  return '\"' + text.replaceAll('\"','\"\"') + '\"';\n}\n\nexport function newId() {\n  if (typeof crypto.randomUUID === 'function') return crypto.randomUUID();\n  const bytes = crypto.getRandomValues(new Uint8Array(16));\n  bytes[6] = (bytes[6] & 15) | 64;\n  bytes[8] = (bytes[8] & 63) | 128;\n  const hex = Array.from(bytes,value => value.toString(16).padStart(2,'0')).join('');\n  return hex.slice(0,8) + '-' + hex.slice(8,12) + '-' + hex.slice(12,16) + '-' +\n    hex.slice(16,20) + '-' + hex.slice(20);\n}\n","type":"application/javascript; charset=utf-8"},"/store.js":{"body":"import {config} from './config.js?v=a625ed1a0ceb';\n\nexport const apiBase = config.eventsUrl.replace(/\\/events$/,'');\nexport const connected = Boolean(config.eventsUrl);\nasync function request(path = '', options = {}) {\n  let response;\n  try {\n    response = await fetch(config.eventsUrl + path, {\n      cache:'no-store',signal:AbortSignal.timeout(20000),...options\n    });\n  } catch {\n    throw new Error('Connection interrupted. Your draft is kept. Retry to confirm the same save.');\n  }\n  const body = await response.json().catch(() => ({}));\n  if (!response.ok) {\n    const error = new Error(body.error || 'Storage request failed. Try again.');\n    error.status = response.status;\n    throw error;\n  }\n  return body;\n}\nexport async function loadEvents(after = 0) {\n  const events = [];\n  let cursor = after;\n  for (;;) {\n    const batch = await request('?after=' + cursor);\n    if (!Array.isArray(batch)) throw new Error('The server returned an invalid event list.');\n    if (!batch.length) return events;\n    if (batch.some(event => !Number.isSafeInteger(event.seq) || event.seq <= cursor)) {\n      throw new Error('The event cursor is invalid. Refresh to retry.');\n    }\n    events.push(...batch);\n    cursor = batch.at(-1).seq;\n    if (batch.length < 500) return events;\n  }\n}\nexport function append(event) {\n  return request('',{\n    method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(event)\n  });\n}\n","type":"application/javascript; charset=utf-8"},"/config.js":{"body":"export const config = { eventsUrl: '/api/events' };\n","type":"application/javascript; charset=utf-8"},"/guide.js":{"body":"export default [[\"R1\", \"Open\", 2, \"Explain the role, call structure and next round.\", null], [\"R1\", \"Experience\", 2, \"Walk me through your last two roles. For each, what did you personally own on social media, and who else was on the team?\", null], [\"R1\", \"Experience\", 3, \"Pick the campaign you are most proud of. What was the goal, what did you personally do, and what was the result?\", null], [\"R1\", \"Experience\", 1, \"How many of your clients or audiences were outside Sri Lanka, and in which countries?\", null], [\"R1\", \"English and client communication\", 4, \"Live reply. “This is Sarah from Bloom Skincare in the UK. Honestly, I’m disappointed. We have paid for 2 months and our Instagram engagement has dropped. My friend’s brand posts every day and gets far more likes. I want us posting daily starting tomorrow.”\", \"Listen for acknowledgement, clarifying questions and a concrete next step.\"], [\"R1\", \"English and client communication\", 3, \"Tell me about a client who was genuinely unhappy with your work. What were the first words you said to them, and how did it end?\", null], [\"R1\", \"AI use\", 2, \"Which AI tools do you use in your work, and what exactly do you use each one for?\", null], [\"R1\", \"AI use\", 2, \"Tell me about the last time AI gave you something you could not use. What was wrong with it, and what did you do?\", null], [\"R1\", \"AI use\", 1, \"If a post created with AI help causes a problem for the client, whose responsibility is it?\", null], [\"R1\", \"Confidentiality and NDA\", 2, \"In your own words, what does an NDA actually cover, and when does it stop applying?\", \"Listen for checking the specific agreement and its terms.\"], [\"R1\", \"Confidentiality and NDA\", 2, \"A prospect asks, “Which other brands do you work with? Can you show me what you did for them?” What do you say?\", null], [\"R1\", \"Logistics\", 4, \"Confirm notice period, earliest start, salary expectation range, hours and time zone flexibility, internet, backup power, quiet call space and ongoing commitments.\", \"For commission-based openings, confirm the approved terms and candidate understanding.\"], [\"R1\", \"Questions and close\", 2, \"Take candidate questions and confirm when they’ll hear back.\", \"R1 total is 30 minutes.\"], [\"R2\", \"Open\", 3, \"Explain the hour and confirm the later writing task is without AI.\", \"Writing task is tracked separately.\"], [\"R2\", \"Brand audit presentation\", 10, \"Candidate presents six slides without interruption.\", null], [\"R2\", \"Audit defence\", 2, \"Why did you choose these three weaknesses over everything else you saw?\", null], [\"R2\", \"Audit defence\", 2, \"What did AI suggest that you rejected, and why did you reject it?\", null], [\"R2\", \"Audit defence\", 2, \"The client says there is no budget for your creative idea. What is your plan B?\", null], [\"R2\", \"Audit defence\", 2, \"If you could do only one of your three improvements first, which one, and what would you measure?\", null], [\"R2\", \"Audit defence\", 2, \"Follow-up and note-taking buffer.\", \"Fills the 10-minute block.\"], [\"R2\", \"Client role-play\", 2, \"“We sell handmade candles in Australia. We need to go viral. Can you guarantee that?”\", null], [\"R2\", \"Client role-play\", 2, \"“Our sales have been flat, so we just want more followers.”\", null], [\"R2\", \"Client role-play\", 2, \"“We want it to feel more premium, but not too serious.”\", null], [\"R2\", \"Client role-play\", 2, \"“I heard you work with [a competitor]. What is their ad budget?”\", \"Confidentiality check.\"], [\"R2\", \"Client role-play\", 2, \"Interrupt mid-sentence with a new concern.\", null], [\"R2\", \"Client role-play\", 3, \"“Honestly, what do you think is wrong with our brand right now?”\", null], [\"R2\", \"Client role-play\", 7, \"Role-play buffer and follow-up.\", \"Includes the original 2-minute buffer and 5 unallocated minutes.\"], [\"R2\", \"Team behaviours\", 10, \"Pick four from the question bank below.\", null], [\"R2\", \"Their questions\", 5, \"Take candidate questions.\", null], [\"R2\", \"Close and next steps\", 2, \"Confirm reference contacts and decision timeline.\", \"R2 total is 60 minutes.\"], [\"Bank\", \"Team behaviours\", null, \"Describe the best manager you have worked with. What made it work?\", null], [\"Bank\", \"Team behaviours\", null, \"Tell me about the harshest feedback you have received, and what you did with it.\", null], [\"Bank\", \"Team behaviours\", null, \"You finish your tasks early on a quiet day. What do you do?\", null], [\"Bank\", \"Team behaviours\", null, \"A teammate is struggling with a client and it is not your account. What do you do?\", null], [\"Bank\", \"Team behaviours\", null, \"Why a small, growing company rather than a large agency?\", null], [\"Bank\", \"Team behaviours\", null, \"What does “being responsible for your work” mean to you?\", null], [\"Scoring\", \"Evidence\", null, \"1 = clear gap. 2 = partial. 3 = meets the requirement. 4 = strong. 5 = consistently strong evidence. Leave untested criteria blank.\", \"Use the same core prompts and criteria for everyone in the same role.\"], [\"Setup\", \"Before outreach\", null, \"Confirm the open role, approved terms and interview criteria with leadership. Explain approved commission terms early when applicable.\", \"If hiring Client Acquisition & Client Relations, adapt the social media audit to a role-relevant exercise before using it.\"], [\"Workflow\", \"Stage updates\", null, \"After each round, save the scorecard and recommendation. Set the candidate’s stage, next action, owner and due date. Log the event.\", \"Keep candidate contact details and scorecards in the shared hiring file with restricted access.\"], [\"Workflow\", \"Final decision\", null, \"Record the decision and reason. Track references, candidate communication and agreement/NDA milestones as applicable.\", \"Record who approved any exception in the candidate note.\"]];\n","type":"application/javascript; charset=utf-8"},"/role.js":{"body":"export const hiringRole = {\n  id:'e2173dde-bc77-409a-96a1-86dcb23841f0',\n  title:'Client Acquisition & Client Relations Specialist',\n  company:'QuidEdge',\n  location:'Remote | Work From Anywhere',\n  employment:'Independent Contractor | Commission-Based only',\n  industry:'Personal Branding | Business Branding | Content Creation',\n  compensation:'100% commission-based. No fixed salary. 10%, 20% or 30% recurring monthly commission on eligible acquired client contracts, subject to the agreed terms.',\n  important:'Only candidates genuinely comfortable with a commission-only compensation structure should apply. Candidates must understand and accept the agreed terms before progressing.',\n  about:[\n    'At QuidEdge, we believe great brands are built through meaningful relationships, creative thinking, and strategies that deliver real business value.',\n    'We are a dedicated team of professionals specialising in personal branding, business branding, content creation, social media management, and business development consulting.',\n    'We work with founders, entrepreneurs, creators, and businesses to help them strengthen their market presence, communicate their value, and build brands that people genuinely connect with.',\n    'We are not interested in simply selling services. We believe in understanding businesses, solving real problems, and building long-term partnerships.',\n    'As we continue expanding internationally, we are looking for passionate and ambitious individuals to join our team as Client Acquisition & Client Relations Specialists.'\n  ],\n  overview:[\n    'This is not a traditional sales position. Successful client acquisition starts with trust, genuine conversations, and understanding what a business actually needs.',\n    'Identify potential clients, build professional relationships, introduce QuidEdge’s solutions, and guide prospects through the acquisition process.',\n    'Maintain strong client relationships and ensure a positive experience throughout their journey with us.'\n  ],\n  responsibilities:[\n    'Identify and research potential clients, including founders, entrepreneurs, creators, and business decision-makers.',\n    'Connect with qualified prospects through LinkedIn, email, professional networks, and other appropriate outreach channels.',\n    'Build genuine relationships instead of relying on generic or aggressive sales pitches.',\n    'Understand prospective clients’ business challenges, branding needs, goals, and growth opportunities.',\n    'Present QuidEdge’s services professionally and communicate how our team can deliver value.',\n    'Conduct discovery conversations, handle enquiries, and coordinate proposals with our internal team.',\n    'Manage the client acquisition journey from initial outreach to successful agreement.',\n    'Maintain accurate records of prospect communications, follow-ups, and client interactions.',\n    'Build and maintain positive, long-term relationships with acquired clients.',\n    'Collaborate with our leadership, creative, and operations teams to ensure smooth client onboarding and communication.',\n    'Represent QuidEdge with professionalism, integrity, and confidentiality.'\n  ],\n  benefits:[\n    ['Work From Anywhere','Enjoy the flexibility of working remotely while connecting with businesses and professionals internationally.'],\n    ['Build Long-Term Income Opportunities','Develop a portfolio of clients that can generate recurring commissions rather than relying solely on one-time sales.'],\n    ['A Supportive Team Culture','People should feel valued, respected, and supported. Collaboration, open communication, and continuous development are central to how we work.'],\n    ['Professional Growth','Gain practical exposure to international business development, client negotiations, brand strategy, and relationship management.'],\n    ['Your Ideas Matter','We encourage initiative and fresh perspectives. Contribute to improving our client acquisition strategies and growing as a team.']\n  ],\n  tiers:[['10%','AUD 300–1,000 / month'],['20%','AUD 1,000–4,999 / month'],['30%','AUD 5,000+ / month']],\n  payment:'Commission is uncapped and continues monthly while the client stays active and paying. Paid monthly in AUD after QuidEdge receives the client’s payment, subject to the agreed contract.',\n  boundary:'The supplied tier ranges overlap at AUD 1,000. Confirm the applicable rate in the candidate’s agreement; this dashboard does not calculate or promise a rate at that boundary.',\n  screening:[\n    ['Experience','Walk through your last two roles. What outreach, discovery, closing and ongoing client relationship work did you personally own?'],\n    ['Evidence','Describe a client you acquired. How did you identify them, qualify the need, build trust and reach an agreement? What was the commercial result?'],\n    ['International communication','Which client markets have you worked with? Respond live to a prospect who asks for a guarantee of sales or viral results.'],\n    ['Commission understanding','Explain the commission-only arrangement in your own words. Is there a fixed salary? When are commissions paid? What terms must you confirm?'],\n    ['Client relations','Tell us about an unhappy client. What did you say first, how did you handle it and what changed?'],\n    ['Confidentiality','A prospect asks for a competitor’s budget and private results. How would you respond?'],\n    ['AI judgment','Which tools support your research and outreach? Give an example you rejected or verified before using.'],\n    ['Remote readiness','Confirm working hours, market time zones, notice period, internet, backup power, call space and other commitments.']\n  ]\n};\n\nexport function defaultRoleRecord(date) {\n  return {id:hiringRole.id,kind:'job',subject_id:null,event_date:date,payload:{\n    title:hiringRole.title,department:'Client Services',location:'Remote · International',\n    employment:'Commission-based',headcount:'1',status:'Open',profile:'client-acquisition-v1',\n    brief:'Independent contractor. No fixed salary. 10% / 20% / 30% recurring commission on eligible acquired contracts under agreed terms. Own prospect research, outreach, discovery, proposals, closing, onboarding and ongoing client relations. Confirm terms and international communication readiness.'\n  }};\n}\n","type":"application/javascript; charset=utf-8"},"/documents.js":{"body":"export const driveRoot = '1n2x6MZ8wqBCPe2bQcU4Z0XQDCV8121Mj';\nexport const maxDocumentBytes = 5 * 1024 * 1024;\nexport async function checkDocument(file) {\n  if (!file || !file.size) throw new Error('Choose a non-empty document.');\n  if (file.size > maxDocumentBytes) throw new Error('Each document must be 5 MB or smaller.');\n  const ext = file.name.split('.').at(-1).toLowerCase();\n  const bytes = new Uint8Array(await file.slice(0,8).arrayBuffer());\n  const pdf = ext === 'pdf' && String.fromCharCode(...bytes.slice(0,5)) === '%PDF-';\n  const doc = ext === 'doc' && [0xd0,0xcf,0x11,0xe0,0xa1,0xb1,0x1a,0xe1].every((b,i)=>bytes[i]===b);\n  const docx = ext === 'docx' && bytes[0]===0x50 && bytes[1]===0x4b && bytes[2]===3 && bytes[3]===4;\n  if (!pdf && !doc && !docx) throw new Error('Use a valid PDF, DOC or DOCX file.');\n  return {extension:ext,mime:pdf?'application/pdf':doc?'application/msword':'application/vnd.openxmlformats-officedocument.wordprocessingml.document'};\n}\nexport function privateFolderSearch(alias) {\n  return 'https://drive.google.com/drive/u/0/search?q=' + encodeURIComponent('type:folder ' + alias);\n}\nexport async function uploadDocument(apiBase,candidate,fullName,file,type,requestId) {\n  const metadata = await checkDocument(file);\n  const buffer = new Uint8Array(await file.arrayBuffer());\n  let binary='';\n  for (let i=0;i<buffer.length;i+=32768) binary+=String.fromCharCode(...buffer.subarray(i,i+32768));\n  let response;\n  try {\n    response=await fetch(apiBase+'/documents',{method:'POST',headers:{'Content-Type':'application/json'},\n      body:JSON.stringify({id:requestId,candidate_id:candidate.id,name:fullName,document_type:type,\n        extension:metadata.extension,data:btoa(binary)}),signal:AbortSignal.timeout(90000)});\n  } catch {throw new Error('Upload interrupted. Retry with the same file. The candidate record is already saved.');}\n  const result=await response.json().catch(()=>({}));\n  if (!response.ok) throw new Error(result.error || 'Document upload failed. Retry with the same file.');\n  return result;\n}\n","type":"application/javascript; charset=utf-8"}};
